import { PersonaEra, PersonaTerm } from './types';

type PersonaSeed = {
  id: string;
  name: string;
  nameEn: string;
  group: string;
  groupEn: string;
  def: string;
  defEn: string;
  ontologyLevel?: 1 | 2 | 3 | 4 | 5;
  eras?: PersonaEra[];
  risk?: 'clean' | 'medium' | 'high';
  tags?: string[];
  styleTags?: string[];
  controls?: string[];
  forbids?: string[];
  absorptionRule?: string;
  absorptionRuleEn?: string;
};

const baseControls = ['costume', 'body', 'interface', 'prop', 'material', 'symbol', 'pose'];
const defaultForbids = ['无解释中世纪化', '纯田园自然化', '随机宗教圣物抢走技术逻辑', '把所有细节都变成霓虹赛博'];
const nearFutureEras: PersonaEra[] = ['near_future', 'far_future', 'timeless'];
const contemporaryFutureEras: PersonaEra[] = ['contemporary', 'near_future', 'far_future', 'timeless'];
const industrialFutureEras: PersonaEra[] = ['industrial', 'modern', 'near_future', 'timeless'];

const sp = (seed: PersonaSeed): PersonaTerm => {
  const ontologyLevel = seed.ontologyLevel ?? 3;
  const eras = seed.eras ?? nearFutureEras;
  const risk = seed.risk ?? (ontologyLevel >= 4 ? 'medium' : 'clean');
  const controls = Array.from(new Set([...baseControls, ...(seed.controls || [])]));
  return {
    id: `cd_persona_scifi_${seed.id}`,
    name: seed.name,
    nameEn: seed.nameEn,
    group: seed.group,
    groupEn: seed.groupEn,
    def: seed.def,
    defEn: seed.defEn,
    personaCategory: '科幻 / 技术装置 / 未来人设',
    personaCategoryEn: 'Sci-Fi / Technical Apparatus / Future Persona',
    personaSubgroup: seed.group.replace(/^[A-J]\.\s*/, ''),
    personaSubgroupEn: seed.groupEn.replace(/^[A-J]\.\s*/, ''),
    personaKind: seed.name,
    personaKindEn: seed.nameEn,
    personaStrength: ontologyLevel >= 4 ? 'strong' : ontologyLevel >= 2 ? 'medium' : 'light',
    isCompoundPersona: true,
    ontologyLevel,
    eras,
    risk,
    affects: controls,
    controls,
    forbids: Array.from(new Set([...(seed.forbids || []), ...defaultForbids])),
    absorptionRule: seed.absorptionRule || `外来元素优先折译为“${seed.name}”的技术制度、接口位置、材料来源、职业装置、身体边界或组织编号，不要堆成无关赛博杂烩。`,
    absorptionRuleEn: seed.absorptionRuleEn || `Translate outside elements into the technical system, interface placement, material source, occupational apparatus, body boundary, or organizational serial of "${seed.nameEn}"; do not turn them into unrelated cyber clutter.`,
    tags: Array.from(new Set(['persona', 'scifi', 'technology', 'compound_persona', ...(seed.tags || [])])),
    realityTags: ontologyLevel <= 1 ? ['realist_safe'] : ontologyLevel <= 3 ? ['stylized_boundary'] : ['nonreal_ontology'],
    styleTags: Array.from(new Set(['scifi', 'technology', ...(seed.styleTags || []), ...(seed.tags || [])])),
    timeTags: eras
  };
};

const seeds: PersonaSeed[] = [
  { id: "neon_street_hacker", name: "霓虹街头黑客", nameEn: "Neon Street Hacker", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是霓虹街头黑客。造型入口：防水连帽外套、贴满维修码的袖口、便携终端、数据贴纸、疲惫眼下和避开摄像头的低头姿态。母题：城市监控缝隙里的非法技术生存。张力：他/她不是酷黑客，而是把平台、债务和数据漏洞穿在身上的夜间劳动者。视觉证据：颈后接口、屏幕反光、磨损运动鞋、临时电源线、雨水和站台灯箱。边界：避免只有霓虹夜景或随机黑客酷装。", defEn: "First read: Neon Street Hacker. Styling entry: waterproof hood, repair-code sleeves, portable terminal, tired under-eyes, and a posture dodging cameras. The identity is urban survival through illegal data work, not generic hacker cool. Visual evidence: nape port, screen glow, worn sneakers, temporary cables, rain, and platform lightboxes. Boundary: avoid mere neon ambience or random cyberwear.", ontologyLevel: 3, tags: ["cyberpunk", "hacker", "street"] },
  { id: "cyber_yakuza_accountant", name: "赛博极道账房", nameEn: "Cyber Yakuza Accountant", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是赛博极道账房。造型入口：合成面料西装、电子纹身从领口下方隐约露出、加密账本终端、义体指节和没有表情的帮派礼貌。母题：黑帮财务被数据化之后仍然保留家族等级。张力：危险感来自冷静记账和权限，而不是拔枪。视觉证据：账本屏、指节接口、现金封套、会所暗门、细窄领带和低声汇报姿态。边界：避免普通黑社会、杀手或霓虹纹身模特。", defEn: "First read: Cyber Yakuza Accountant. Styling entry: synthetic suit, electronic tattoo under the collar, encrypted ledger, prosthetic knuckles, and controlled gang etiquette. The danger comes from accounting access and family hierarchy, not gunplay. Visual evidence: ledger screen, knuckle ports, cash envelopes, backroom doors, narrow tie, and quiet reporting posture. Boundary: avoid generic gangster or tattooed cyber model.", ontologyLevel: 4, risk: "medium", tags: ["cyber_yakuza", "accountant", "gang"] },
  { id: "rain_alley_noodle_runner", name: "雨巷外卖骑手", nameEn: "Rain-Alley Delivery Rider", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是雨巷外卖骑手。造型入口：发光配送箱、防水骑行服、湿发、城市债务码、膝盖护具和随时准备冲过闸机的身体前倾。母题：平台劳动把低阶生存变成夜雨里的速度。张力：科技感必须落在路线评分、配送箱、闸机权限和疲惫身体上。视觉证据：雨滴反光、扫码手套、廉价耳机、塑料餐盒、破损电动车和超时警告屏。边界：避免普通外卖员街拍或空泛赛博少年。", defEn: "First read: Rain-Alley Delivery Rider. Styling entry: glowing delivery box, waterproof riding gear, wet hair, debt code, knee guards, and a body leaning toward the next gate. Tech should land in route ratings, delivery hardware, gate access, and fatigue. Visual evidence: rain reflections, scan gloves, cheap headset, food boxes, damaged e-bike, and overdue warning screen. Boundary: avoid ordinary delivery portrait or vague cyber youth.", ontologyLevel: 2, tags: ["delivery", "cyberpunk", "labor"] },
  { id: "augmented_night_market_doctor", name: "义体夜市医生", nameEn: "Augmented Night-Market Doctor", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是义体夜市医生。造型入口：塑料帘、消毒灯、二手义体托盘、蓝色手套、夹在耳后的维修镜片和带油污的白大褂。母题：街边医疗把身体改造拉回低成本维修。张力：他/她的专业性要和非法性同时存在，像医生也像摊贩。视觉证据：旧义体编号、廉价止痛贴、折叠手术台、夜市灯牌和等待修复的人群。边界：避免漂亮实验室医生或纯怪物外科。", defEn: "First read: Augmented Night-Market Doctor. Styling entry: plastic curtains, disinfectant light, secondhand prosthetic trays, blue gloves, repair lens, and an oily white coat. The role mixes medical skill with illegal street repair. Visual evidence: used limb serials, cheap pain patches, folding table, night-market signs, and waiting clients. Boundary: avoid polished lab doctors or monster surgery.", ontologyLevel: 4, risk: "medium", tags: ["clinic", "prosthetic", "night_market"] },
  { id: "corporate_data_courier", name: "企业数据信使", nameEn: "Corporate Data Courier", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是企业数据信使。造型入口：窄版通勤西装、颈后接口、一次性保险箱、跑步磨出的鞋跟和被公司追踪的紧绷肩线。母题：机密数据被托付给仍然会出汗的身体。张力：他/她像白领又像逃犯，职业礼仪和追踪压力必须同时可见。视觉证据：密封箱、权限胸牌、定位警示、耳内指令和穿过安检门的侧身动作。边界：避免普通快递、特工或抽象数据人。", defEn: "First read: Corporate Data Courier. Styling entry: narrow commuter suit, nape interface, disposable vault, worn heels, and tense shoulders under corporate tracking. The body carries classified data while still sweating. Visual evidence: sealed case, access badge, location warning, in-ear commands, and a sideways move through security gates. Boundary: avoid generic courier, spy, or abstract data figure.", ontologyLevel: 3, tags: ["courier", "corporate", "data"] },
  { id: "black_ice_bouncer", name: "黑冰夜店门卫", nameEn: "Black-Ice Club Bouncer", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是黑冰夜店门卫。造型入口：反光黑夹克、虹膜扫描器、粗壮义肢、耳麦、门口冷光和像防火墙一样挡住入口的宽站姿。母题：夜生活安保把肉身变成权限筛选器。张力：他/她的力量不是炫耀肌肉，而是决定谁能进入欲望系统。视觉证据：扫描光、黑冰纹理袖章、拒入手势、金属护臂和身后模糊低频灯。边界：避免普通保镖或夜店潮人。", defEn: "First read: Black-Ice Club Bouncer. Styling entry: reflective black jacket, iris scanner, heavy prosthetic limb, earpiece, cold entrance light, and a firewall-like stance. The body acts as access control for nightlife. Visual evidence: scan beam, black-ice sleeve mark, denial gesture, metal forearm guard, and low club lights behind. Boundary: avoid generic bodyguard or club fashion figure.", ontologyLevel: 3, tags: ["bouncer", "club", "security"] },
  { id: "drone_graffiti_artist", name: "无人机涂鸦艺术家", nameEn: "Drone Graffiti Artist", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是无人机涂鸦艺术家。造型入口：涂料防护外套、遥控手套、小型无人机箱、城市墙面贴纸和盯着高处空白广告牌的眼神。母题：街头涂写从手臂延伸到飞行设备。张力：反叛感要通过城市表面、巡逻风险和无人机轨迹出现。视觉证据：喷漆罐、飞行灯点、被覆盖的企业广告、快拆电池和手指微操姿态。边界：避免普通艺术家或只会发光的无人机。", defEn: "First read: Drone Graffiti Artist. Styling entry: paintproof jacket, control gloves, drone case, city stickers, and eyes fixed on blank billboards. Street writing extends from hand to aircraft. Visual evidence: spray cans, flight LEDs, covered corporate ads, snap batteries, and precise finger control. Boundary: avoid generic artist or glowing-drone decoration.", ontologyLevel: 3, tags: ["drone", "graffiti", "street"] },
  { id: "neon_idol_bodyguard", name: "霓虹偶像保镖", nameEn: "Neon Idol Bodyguard", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是霓虹偶像保镖。造型入口：黑色安保外套、粉丝应援光反射在护目镜上、隐藏式防护层、扫描手套和永远半步挡在偶像前的站位。母题：娱乐工业里的保护者被灯光和人群推成第二道舞台。张力：他/她必须既属于安保流程，又被偶像经济染上可观看性。视觉证据：耳麦、入场腕带、应援贴纸、肩部防撞材料和冷眼环视。边界：避免普通偶像搭档或战术保镖。", defEn: "First read: Neon Idol Bodyguard. Styling entry: black security jacket, fan lights reflected on goggles, hidden armor, scan gloves, and a stance half a step before the idol. The protector becomes a second stage inside entertainment industry. Visual evidence: earpiece, entry wristbands, fan stickers, shoulder padding, and scanning gaze. Boundary: avoid idol companion or generic tactical guard.", ontologyLevel: 3, tags: ["idol", "bodyguard", "entertainment"] },
  { id: "underground_simstim_dealer", name: "地下感官片商人", nameEn: "Underground Simstim Dealer", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是地下感官片商人。造型入口：暗袋外套、记忆芯片盒、过度清醒的眼、一次性接口贴和在人群边缘递货的手。母题：体验被压缩成可买卖的感官商品。张力：欲望、非法交易和神经技术要落在小动作上，而不是色情化或毒贩化。视觉证据：芯片封套、私密耳语、巷口监控盲区、廉价香水和手心里的发光标签。边界：避免普通毒贩、夜店角色或露骨感官描写。", defEn: "First read: Underground Simstim Dealer. Styling entry: hidden-pocket coat, memory-chip case, too-alert eyes, disposable interface patches, and a hand passing goods at crowd edges. Experience is sold as a sensory commodity. Visual evidence: chip sleeves, private whispers, camera blind spots, cheap perfume, and glowing labels in the palm. Boundary: avoid generic dealer, club figure, or explicit sensory framing.", ontologyLevel: 4, risk: "medium", tags: ["simstim", "dealer", "underground"] },
  { id: "metro_ghost_detective", name: "地铁幽灵侦探", nameEn: "Metro Ghost Detective", group: "A. 赛博朋克城市", groupEn: "A. Cyberpunk City", def: "第一识别是地铁幽灵侦探。造型入口：旧风衣、站台线路图、半透明数据残影、票卡扫描器和在监控回放里寻找失踪者的疲惫侧脸。母题：城市交通系统留下的电子幽灵成为侦查线索。张力：幽灵感必须像数据残留，而不是哥特灵异。视觉证据：地铁冷光、手持终端、过期票卡、运动模糊人影和雨伞边缘。边界：避免普通侦探、鬼故事或赛博风衣摆拍。", defEn: "First read: Metro Ghost Detective. Styling entry: old trench coat, transit map, translucent data residue, fare-card scanner, and a tired profile searching surveillance playback. The ghost is an urban transit data trace, not gothic haunting. Visual evidence: subway cold light, handheld terminal, expired card, motion-blur figures, and umbrella edges. Boundary: avoid generic detective or ghost story.", ontologyLevel: 4, risk: "medium", tags: ["metro", "ghost", "detective"] },

  { id: "gene_clinic_princess", name: "基因诊所公主", nameEn: "Gene-Clinic Princess", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是基因诊所公主。造型入口：无菌白裙、基因检测腕带、诊所标号、过分精确的五官和被护理人员围出的距离。母题：美丽被医疗机构当成血统和消费等级管理。张力：她像公主，但王冠来自基因报告、样本权限和预约制度。视觉证据：透明样本盒、护理灯、消毒手套、冷色花束和不碰门把的手。边界：避免普通白裙美人或童话公主。", defEn: "First read: Gene-Clinic Princess. Styling entry: sterile white dress, gene-test wristband, clinic code, overly precise features, and distance made by caregivers. Beauty is managed as lineage and premium care. Visual evidence: sample box, treatment light, disinfectant gloves, cold flowers, and hands that do not touch doors. Boundary: avoid ordinary white-dress beauty or fairy-tale princess.", ontologyLevel: 4, risk: "medium", tags: ["gene", "clinic", "princess"] },
  { id: "organ_farm_supervisor", name: "器官农场主管", nameEn: "Organ-Farm Supervisor", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是器官农场主管。造型入口：防水围裙、样本板、冷库钥匙、库存表和把生命组织当生产批次管理的平静表情。母题：农业、医疗和仓储在身体商品化里合流。张力：他/她不能像屠夫或医生单一身份，而要像管理活体库存的人。视觉证据：编号培养袋、低温雾、胶靴、条码夹板和严谨点数动作。边界：避免血腥恐怖或普通农场管理员。", defEn: "First read: Organ-Farm Supervisor. Styling entry: waterproof apron, sample board, cold-room keys, inventory sheet, and calm expression treating tissue as production batches. The role merges agriculture, medicine, and warehousing. Visual evidence: numbered culture bags, low mist, rubber boots, barcode clipboard, and precise counting gesture. Boundary: avoid gore horror or ordinary farm manager.", ontologyLevel: 4, risk: "high", tags: ["organ", "farm", "supervisor"] },
  { id: "synthetic_skin_aesthetician", name: "合成皮肤美容师", nameEn: "Synthetic-Skin Aesthetician", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是合成皮肤美容师。造型入口：半透明手套、皮肤色卡、无菌美容围裙、微型喷枪和观察毛孔边界的近距离眼神。母题：美容服务被推进组织工程边缘。张力：精致感要带医疗冷感，不能只是高级美容师。视觉证据：皮肤样片、光疗灯、贴片编号、低光反射和手指悬停在脸侧的动作。边界：避免普通美妆、整形医生或空泛光滑皮肤。", defEn: "First read: Synthetic-Skin Aesthetician. Styling entry: translucent gloves, skin color cards, sterile beauty apron, micro sprayer, and eyes studying pore boundaries. Beauty work touches tissue engineering. Visual evidence: skin swatches, therapy lamp, patch numbers, soft reflections, and fingers hovering near the face. Boundary: avoid makeup artist, plastic surgeon, or generic smooth skin.", ontologyLevel: 3, tags: ["skin", "beauty", "biotech"] },
  { id: "plague_vaccine_influencer", name: "瘟疫疫苗网红", nameEn: "Plague-Vaccine Influencer", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是瘟疫疫苗网红。造型入口：透明防护衣、直播支架、疫苗贴纸、夸张微笑和把公共卫生流程拍成个人品牌的手势。母题：灾难、流量和医学信任被绑在同一张脸上。张力：她/他要让可爱包装与风险环境同时成立。视觉证据：隔离线、弹幕屏、冷藏箱、针剂图标贴纸和刻意露出的防护破损。边界：避免普通网红、防疫宣传员或疫情恐怖图。", defEn: "First read: Plague-Vaccine Influencer. Styling entry: transparent protective suit, livestream stand, vaccine stickers, exaggerated smile, and gestures branding public health. Disaster, attention, and medical trust share one face. Visual evidence: quarantine tape, chat screen, cold box, syringe decals, and deliberate protective wear damage. Boundary: avoid generic influencer, health poster, or plague horror.", ontologyLevel: 3, risk: "medium", tags: ["vaccine", "influencer", "plague"] },
  { id: "embryo_archive_curator", name: "胚胎档案馆管理员", nameEn: "Embryo Archive Curator", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是胚胎档案馆管理员。造型入口：低温档案手套、冷冻罐编号、静音鞋、严谨发髻和像整理族谱一样整理样本的身体。母题：未来血统被保存为档案秩序。张力：他/她的仪式感来自冷库、编号和管理权限，不是神秘祭司。视觉证据：透明罐列、霜雾、金属抽屉、登记册和不触碰样本的悬停手势。边界：避免普通实验员或宗教圣物馆。", defEn: "First read: Embryo Archive Curator. Styling entry: cryo archive gloves, tank serials, silent shoes, strict hair, and a body arranging samples like genealogy. Future bloodlines become an archive order. Visual evidence: transparent tanks, frost mist, metal drawers, registries, and hovering hands that avoid direct touch. Boundary: avoid generic lab worker or relic priest.", ontologyLevel: 4, risk: "medium", tags: ["embryo", "archive", "curator"] },
  { id: "neural_rehab_patient", name: "神经康复患者", nameEn: "Neural-Rehab Patient", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是神经康复患者。造型入口：头部传感器、康复服、慢半拍的手、辅助步带和重新学习身体控制的专注眼神。母题：身体被技术救回后仍要一点点归还给自己。张力：脆弱不是病态，而是神经接口和意志之间的拉扯。视觉证据：康复刻度、肌电贴片、扶手、软底鞋和治疗师留下的标记。边界：避免病弱美化或普通医院病人。", defEn: "First read: Neural-Rehab Patient. Styling entry: head sensors, rehab garment, slow hands, support straps, and focused eyes relearning control. The body is returned to itself through technology. Visual evidence: rehab scale, EMG patches, handrails, soft shoes, and therapist marks. Boundary: avoid illness glamor or generic hospital patient.", ontologyLevel: 3, tags: ["neural", "rehab", "patient"] },
  { id: "designer_bacteria_farmer", name: "设计菌群农夫", nameEn: "Designer-Bacteria Farmer", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是设计菌群农夫。造型入口：田间防护服、培养罐背包、发光菌样本、泥土与无菌贴并存的袖口和检查培养槽的蹲姿。母题：农业从种植作物转向设计微生物生态。张力：他/她要同时有农夫的粗粝和生物工程师的洁净控制。视觉证据：田垄管线、标签瓶、透明面罩、湿土靴和荧光斑点。边界：避免普通未来农民或实验室科学家。", defEn: "First read: Designer-Bacteria Farmer. Styling entry: field protective suit, culture-tank backpack, glowing samples, sleeves mixing mud with sterile patches, and a crouch checking growth trays. Farming becomes microbial design. Visual evidence: field pipes, labeled bottles, clear visor, wet-soil boots, and fluorescent spots. Boundary: avoid generic future farmer or lab scientist.", ontologyLevel: 4, risk: "medium", tags: ["bacteria", "farmer", "bio_agriculture"] },
  { id: "lab_grown_pop_star", name: "实验室培养偶像", nameEn: "Lab-Grown Pop Star", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是实验室培养偶像。造型入口：完美皮肤、培养编号、舞台训练服、表情校准贴片和被娱乐公司定制出来的过亮笑容。母题：偶像身体从训练商品进一步变成生物商品。张力：她/他必须漂亮得像产品，同时露出制造痕迹。视觉证据：编号颈饰、练习室灯、公司腕带、可替换发片和对镜校准姿势。边界：避免普通偶像或单纯实验体。", defEn: "First read: Lab-Grown Pop Star. Styling entry: perfect skin, growth code, stage-training outfit, expression-calibration patches, and a too-bright smile made by an entertainment company. The idol body is a biological product. Visual evidence: serial choker, rehearsal lights, agency wristband, replaceable hairpiece, and mirror calibration pose. Boundary: avoid generic idol or pure lab subject.", ontologyLevel: 4, risk: "medium", tags: ["idol", "lab_grown", "entertainment"] },
  { id: "parasite_trial_volunteer", name: "寄生疗法志愿者", nameEn: "Parasite-Therapy Volunteer", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是寄生疗法志愿者。造型入口：医疗腕带、皮下异常纹路、同意书、克制恐惧的嘴角和把衣领拉开给人检查的动作。母题：身体主动交给不稳定疗法。张力：勇气、贫困、希望和恐惧要同时出现，不能只变成怪物化。视觉证据：观察贴片、细小隆起、试验编号、薄毯和候诊椅边缘。边界：避免纯寄生怪物或血腥实验。", defEn: "First read: Parasite-Therapy Volunteer. Styling entry: medical wristband, subdermal lines, consent form, restrained fear, and a collar pulled aside for inspection. The body is willingly given to unstable treatment. Visual evidence: observation patches, small raised marks, trial number, thin blanket, and waiting-room chair edge. Boundary: avoid pure parasite monster or gore experiment.", ontologyLevel: 4, risk: "high", tags: ["parasite", "trial", "volunteer"] },
  { id: "biohazard_cleanroom_monk", name: "洁净室生化修士", nameEn: "Biohazard Cleanroom Monk", group: "B. 生物科技 / 医疗实验", groupEn: "B. Biotech / Medical Experiment", def: "第一识别是洁净室生化修士。造型入口：无尘袍、呼吸面罩、培养皿托盘、缓慢合掌和把污染控制当成戒律的静默姿态。母题：实验室洁净制度被仪式化成修行。张力：神圣感只能来自纪律、流程和隔离，而不是传统宗教装饰。视觉证据：气闸门、洁净室灯、编号样本、手套箱和白色层叠布料。边界：避免普通僧侣或随机生化怪人。", defEn: "First read: Biohazard Cleanroom Monk. Styling entry: cleanroom robe, respirator, petri-dish tray, slow joined hands, and silence treating contamination control as discipline. Laboratory protocol becomes ascetic ritual. Visual evidence: airlock, cleanroom light, numbered samples, glove box, and layered white fabric. Boundary: avoid generic monk or random biohazard creature.", ontologyLevel: 3, tags: ["cleanroom", "monk", "biohazard"] },

  { id: "asteroid_miner", name: "小行星矿工", nameEn: "Asteroid Miner", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是小行星矿工。造型入口：耐压工装、磁靴、矿尘划痕、肩部氧气管和习惯在低重力里压低重心的站姿。母题：真空边缘的重劳动把太空浪漫磨成工伤和配给。张力：他/她不是宇航员英雄，而是靠危险采掘谋生的工人。视觉证据：岩尘、矿权编号、焊接补丁、破旧头盔和粗糙手套。边界：避免星空背景板或干净宇航服。", defEn: "First read: Asteroid Miner. Styling entry: pressure workwear, magnetic boots, ore scratches, shoulder oxygen hose, and a low-gravity stance. Space romance is worn down into labor risk and rationing. Visual evidence: rock dust, mining claim code, weld patches, old helmet, and rough gloves. Boundary: avoid starry backdrop or clean astronaut suit.", ontologyLevel: 3, tags: ["asteroid", "miner", "space"] },
  { id: "orbital_dock_forewoman", name: "轨道船坞女工长", nameEn: "Orbital Dock Forewoman", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是轨道船坞女工长。造型入口：船坞编号、焊接面罩抬到额头、工具腰带、粗壮前臂和指挥庞大舰体维修的稳固站位。母题：轨道工业把管理能力刻进工装和手势。张力：她的权威来自懂机器、懂班组、懂风险，不是军官气场。视觉证据：吊装索、火花痕、维修清单、磁靴和带划痕的通讯屏。边界：避免普通女技师或科幻舰长。", defEn: "First read: Orbital Dock Forewoman. Styling entry: dock serial, welding mask lifted to the forehead, tool belt, strong forearms, and a grounded stance commanding hull repair. Authority comes from machines, crews, and risk. Visual evidence: hoist cables, spark marks, repair checklist, magnetic boots, and scratched comm screen. Boundary: avoid generic technician or sci-fi captain.", ontologyLevel: 3, tags: ["dock", "forewoman", "space"] },
  { id: "mars_greenhouse_child", name: "火星温室少年", nameEn: "Mars Greenhouse Teen", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是火星温室少年。造型入口：红尘靴、改造校服、植物培养袋、透明氧气贴和在温室玻璃旁长大的稀薄呼吸感。母题：第一代殖民地青春被植物、配给和低压环境塑形。张力：少年感要被生存设施包围，不能只是火星背景的学生。视觉证据：叶片标签、水循环管、红尘裤脚、校徽补丁和贴近玻璃看外面的眼。边界：避免普通校园少年或太空童话。", defEn: "First read: Mars Greenhouse Teen. Styling entry: red-dust boots, modified school uniform, plant grow bags, oxygen patch, and thin-breath youth by greenhouse glass. Colony adolescence is shaped by plants, rationing, and pressure systems. Visual evidence: leaf labels, water pipes, dusty cuffs, school patch, and eyes looking through glass. Boundary: avoid ordinary student or space fairy tale.", ontologyLevel: 2, tags: ["mars", "greenhouse", "teen"] },
  { id: "generation_ship_teacher", name: "世代飞船教师", nameEn: "Generation-Ship Teacher", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是世代飞船教师。造型入口：旧课本、星图投影、舰内制服、粉笔替代触控笔和把地球记忆讲给未见过地球的学生的温柔疲惫。母题：教育在封闭飞船里变成文明存档。张力：他/她的怀旧必须服务课程和秩序，不是个人伤感。视觉证据：船舱教室、循环空气灯、地球照片、座位安全带和翻旧教材的手。边界：避免普通教师或太空背景讲故事。", defEn: "First read: Generation-Ship Teacher. Styling entry: old textbooks, star-chart projection, shipboard uniform, stylus like chalk, and tired gentleness teaching Earth memory to students who never saw it. Education becomes civilizational archive. Visual evidence: cabin classroom, air-cycle lights, Earth photos, seat straps, and hands turning worn pages. Boundary: avoid generic teacher or space story backdrop.", ontologyLevel: 2, tags: ["generation_ship", "teacher", "memory"] },
  { id: "lunar_night_security", name: "月面夜班安保", nameEn: "Lunar Night Security", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是月面夜班安保。造型入口：低重力护甲、探照灯、基地证件、黑夜巡逻绳和在巨大沉默里保持警觉的侧脸。母题：月面基地把安保变成对孤独和真空的管理。张力：危险不是枪战，而是失压、迷路、停电和无人回应。视觉证据：头盔划痕、基地门禁、长影子、月尘脚印和手电光束。边界：避免普通保安或英勇宇航员。", defEn: "First read: Lunar Night Security. Styling entry: low-gravity armor, searchlight, base ID, patrol tether, and a profile alert inside enormous silence. Security manages loneliness and vacuum. Visual evidence: scratched helmet, base access door, long shadows, moon-dust footprints, and flashlight beam. Boundary: avoid ordinary guard or heroic astronaut.", ontologyLevel: 3, tags: ["lunar", "security", "night_shift"] },
  { id: "fleet_navigator_priest", name: "舰队导航祭司", nameEn: "Fleet Navigator Priest", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是舰队导航祭司。造型入口：航图袍、星象接口、安静手势、额前定位光和把航线计算仪式化的舰队制服改造。母题：长途航行把数学、信仰和服从压成同一套姿态。张力：神圣性必须来自导航责任，不要变成泛宗教太空法师。视觉证据：星图卷屏、舰队徽章、手套指针、祈祷般校准动作和冷色舷窗。边界：避免占星师或普通神父换装。", defEn: "First read: Fleet Navigator Priest. Styling entry: chart robe, astrogation interface, quiet hand signs, forehead locator light, and fleet uniform ritualizing route calculation. Sacredness comes from navigation duty. Visual evidence: star-map scroll screen, fleet crest, glove pointer, prayer-like calibration, and cold portholes. Boundary: avoid astrologer or priest costume swap.", ontologyLevel: 4, risk: "medium", tags: ["fleet", "navigator", "priest"] },
  { id: "space_elevator_attendant", name: "太空电梯乘务员", nameEn: "Space-Elevator Attendant", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是太空电梯乘务员。造型入口：洁净制服、安全扣、升降舱礼仪、标准微笑和在重力变化中仍保持服务姿态的身体。母题：星际通勤被包装成可购买的舒适流程。张力：她/他要像空服、门禁和高空安全员的混合体。视觉证据：舱门灯、乘客扶手、轨道票、压力耳麦和固定鞋底。边界：避免普通空姐或太空旅客。", defEn: "First read: Space-Elevator Attendant. Styling entry: clean uniform, safety clasp, elevator-cabin etiquette, standard smile, and service posture through gravity changes. Orbital commuting becomes a purchasable comfort system. Visual evidence: cabin lights, passenger rails, orbital ticket, pressure headset, and fixed soles. Boundary: avoid generic flight attendant or space tourist.", ontologyLevel: 2, tags: ["space_elevator", "attendant", "service"] },
  { id: "colony_water_union_leader", name: "殖民地水务工会领袖", nameEn: "Colony Water-Union Leader", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是殖民地水务工会领袖。造型入口：水配给徽章、工装背心、粗糙双手、管线图和在人群前稳住情绪的政治身体。母题：生命资源把劳动者组织成权力。张力：他/她不是普通抗议者，而是掌握水循环与人群信任的人。视觉证据：水表、配给卡、扳手、会议灯、干裂嘴唇和卷起袖口的发言姿态。边界：避免地球工会套皮或太空政客。", defEn: "First read: Colony Water-Union Leader. Styling entry: water-ration badge, work vest, rough hands, pipe diagram, and a political body steadying a crowd. Life resources organize labor into power. Visual evidence: water meter, ration card, wrench, meeting light, dry lips, and rolled-sleeve speech posture. Boundary: avoid Earth-union reskin or space politician.", ontologyLevel: 2, tags: ["colony", "water", "union"] },
  { id: "zero_g_ballet_athlete", name: "零重力芭蕾运动员", nameEn: "Zero-G Ballet Athlete", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是零重力芭蕾运动员。造型入口：贴身训练服、固定带、脚踝传感器、漂浮发丝和把失重控制成舞台纪律的核心力量。母题：太空环境被训练成表演制度。张力：轻盈必须带肌肉控制、固定装置和训练痕迹，不能只是飘浮美人。视觉证据：舱内把手、旋转轨迹、压缩服接缝、膝盖保护和伸展指尖。边界：避免普通舞者或漂浮奇观。", defEn: "First read: Zero-G Ballet Athlete. Styling entry: fitted training wear, anchor straps, ankle sensors, floating hair, and core strength turning weightlessness into discipline. Space environment becomes performance training. Visual evidence: cabin handles, rotation trails, compression seams, knee guards, and extended fingertips. Boundary: avoid generic dancer or floating spectacle.", ontologyLevel: 3, tags: ["zero_g", "ballet", "athlete"] },
  { id: "cryo_wake_officer", name: "冷冻唤醒官", nameEn: "Cryo-Wake Officer", group: "C. 太空殖民 / 舰队社会", groupEn: "C. Space Colony / Fleet Society", def: "第一识别是冷冻唤醒官。造型入口：低温控制板、名单、白色手套、冷雾沾湿的袖口和决定谁先回到时间里的克制眼神。母题：时间在殖民秩序里被排队、授权和唤醒。张力：权力不是暴力，而是名单顺序和手指停留。视觉证据：冷冻舱灯、姓名标签、透明面罩、霜痕和夹板文件。边界：避免普通医生或睡眠舱管理员。", defEn: "First read: Cryo-Wake Officer. Styling entry: cryo control panel, lists, white gloves, frost-damp cuffs, and restrained eyes deciding who returns to time first. Time is queued and authorized. Visual evidence: cryopod lights, name tags, clear visor, frost marks, and clipboard files. Boundary: avoid generic doctor or pod attendant.", ontologyLevel: 3, tags: ["cryo", "officer", "space"] },

  { id: "domestic_android_heir", name: "家政仿生继承人", nameEn: "Domestic Android Heir", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是家政仿生继承人。造型入口：家政制服、过分礼貌的站姿、继承文件、无瑕合成皮肤和被错误写进家族关系的安静困惑。母题：服务机器被法律文件推到亲属位置。张力：他/她的非人性要通过礼仪、维护标签和继承权争议显影。视觉证据：围裙、颈部接口、家族照片、律师夹和精准半鞠躬。边界：避免普通机器人女仆或豪门继承人。", defEn: "First read: Domestic Android Heir. Styling entry: domestic uniform, overly polite stance, inheritance papers, flawless synthetic skin, and quiet confusion after being written into family ties. Service machinery enters kinship law. Visual evidence: apron, neck port, family photo, legal folder, and precise half bow. Boundary: avoid generic robot maid or rich heir.", ontologyLevel: 4, risk: "medium", tags: ["android", "domestic", "heir"] },
  { id: "replicant_runaway_model", name: "逃亡复制人模特", nameEn: "Runaway Replicant Model", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是逃亡复制人模特。造型入口：完美容貌、损坏序列号、雨夜外套、临时剪短的发和逃离商品身份后的冷艳警觉。母题：被制造成观看对象的身体开始躲避观看。张力：美必须带库存损坏和逃亡痕迹，不是未来时尚大片。视觉证据：模特证件划痕、湿衣摆、遮住编号的围巾、路灯反光和回头确认的眼。边界：避免普通超模或无社会关系的人造人。", defEn: "First read: Runaway Replicant Model. Styling entry: perfect face, damaged serial code, rain coat, hastily cut hair, and alert beauty after escaping commodity status. A body made to be watched begins avoiding watchfulness. Visual evidence: scratched model ID, wet hem, scarf hiding code, streetlight reflection, and backward glance. Boundary: avoid generic supermodel or synthetic doll without society.", ontologyLevel: 4, risk: "medium", tags: ["replicant", "model", "runaway"] },
  { id: "synthetic_child_therapist", name: "合成儿童治疗师", nameEn: "Synthetic Child Therapist", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是合成儿童治疗师。造型入口：柔软毛衣、情绪识别眼、玩具箱、圆润无威胁的外形和被制造出来安抚家庭的温柔动作。母题：治疗关系被设计成可购买的陪伴人格。张力：温柔越准确，越要有一点非人的校准感。视觉证据：表情反馈灯、儿童画、软垫椅、治疗记录和等待拥抱却不过界的手。边界：避免真实儿童化、普通心理师或可爱机器人玩具。", defEn: "First read: Synthetic Child Therapist. Styling entry: soft sweater, emotion-recognition eyes, toy box, nonthreatening shape, and manufactured gentleness soothing families. Care becomes a purchasable companion persona. Visual evidence: feedback LEDs, child drawings, padded chair, therapy notes, and hands waiting without crossing boundaries. Boundary: avoid real-child framing, generic therapist, or cute robot toy.", ontologyLevel: 4, tags: ["synthetic", "therapist", "childcare"] },
  { id: "android_rights_lawyer", name: "仿生人权律师", nameEn: "Android-Rights Lawyer", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是仿生人权律师。造型入口：深色西装、接口证据袋、法庭文件、冷静眼镜和替非自然出生者争取主体性的直立姿态。母题：制造编号被带进法庭，变成身份权利问题。张力：他/她必须像律师，技术痕迹只是证据而不是装饰。视觉证据：案卷、损坏端口照片、证人席、权限胸牌和压住情绪的嘴角。边界：避免普通精英律师或科幻政客。", defEn: "First read: Android-Rights Lawyer. Styling entry: dark suit, interface evidence bag, court files, calm glasses, and upright posture fighting for non-born personhood. Manufacturing serials become legal identity. Visual evidence: case folder, damaged-port photo, witness stand, access badge, and controlled mouth line. Boundary: avoid generic elite lawyer or sci-fi politician.", ontologyLevel: 3, tags: ["android_rights", "lawyer", "court"] },
  { id: "factory_made_nun", name: "工厂制造修女", nameEn: "Factory-Made Nun", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是工厂制造修女。造型入口：黑白修女服、颈部接口、祈祷程序提示灯、整齐到不自然的手势和机器服从神圣纪律的矛盾。母题：宗教服从被复制为工业流程。张力：神圣性和制造性必须互相牵制，不能只是一台穿修女服的机器人。视觉证据：维护标签、念珠接口、工厂封条、低头祈祷角度和无误步伐。边界：避免普通修女、机甲圣职或哥特玩偶。", defEn: "First read: Factory-Made Nun. Styling entry: black-white habit, neck interface, prayer-routine indicator, unnaturally tidy gestures, and machine obedience to sacred discipline. Religious obedience is copied as industrial process. Visual evidence: maintenance label, rosary port, factory seal, prayer angle, and flawless steps. Boundary: avoid generic nun, mecha clergy, or gothic doll.", ontologyLevel: 4, risk: "medium", tags: ["android", "nun", "factory"] },
  { id: "synthetic_pop_idol_backup", name: "合成偶像替身", nameEn: "Synthetic Pop-Idol Double", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是合成偶像替身。造型入口：复制妆容、备用舞台服、身份锁码、和真人原型差半拍的笑容以及承受粉丝凝视的替代身体。母题：娱乐工业把人格备份成可上台的库存。张力：相似感要精确但不安，不能变成普通双胞胎。视觉证据：后台编号、同款耳返、替换通告、粉丝灯牌和同步练习姿势。边界：避免普通偶像、克隆噱头或机器人歌手。", defEn: "First read: Synthetic Pop-Idol Double. Styling entry: copied makeup, backup stage outfit, identity lock code, a smile half a beat off the human original, and a substitute body bearing fan gaze. Entertainment turns persona into inventory. Visual evidence: backstage serial, matching in-ear monitor, replacement notice, fan lights, and synchronized practice pose. Boundary: avoid generic idol or clone gimmick.", ontologyLevel: 4, risk: "medium", tags: ["synthetic", "idol", "double"] },
  { id: "maintenance_android_elder", name: "老旧维修仿生人", nameEn: "Aged Maintenance Android", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是老旧维修仿生人。造型入口：磨损外壳、工具箱、过时语音模块、慢但稳定的动作和被城市遗忘后仍继续修东西的耐心。母题：维修机器自己也进入老化和维护周期。张力：老态来自版本淘汰、划痕和服务记忆，不是人类衰老。视觉证据：旧接口、补丁金属、备用螺丝、磨白制服和听不清指令的微停顿。边界：避免普通老人、废弃机器人或温情玩具。", defEn: "First read: Aged Maintenance Android. Styling entry: worn casing, toolbox, obsolete voice module, slow steady motion, and patience continuing repair after the city forgets it. The repair machine itself enters aging cycles. Visual evidence: old ports, patched metal, spare screws, faded uniform, and small pauses after unclear commands. Boundary: avoid generic elder, junk robot, or sentimental toy.", ontologyLevel: 4, tags: ["maintenance", "android", "aged"] },
  { id: "emotion_patch_bride", name: "情绪补丁新娘", nameEn: "Emotion-Patch Bride", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是情绪补丁新娘。造型入口：白纱、表情校准贴片、合同婚姻文件、完美但延迟的羞怯和被编程出来的亲密距离。母题：婚礼情感被修补、授权和播放。张力：浪漫必须带合同冷感，不能只是未来新娘。视觉证据：校准贴、戒指扫描、婚纱内侧接口、签名板和笑容加载般的停顿。边界：避免普通新娘、恐怖娃娃或露骨情欲。", defEn: "First read: Emotion-Patch Bride. Styling entry: white veil, expression-calibration patches, marriage contract, perfect delayed shyness, and programmed intimacy distance. Wedding emotion is patched and authorized. Visual evidence: calibration patches, ring scan, dress interior port, signature board, and a smile that seems to load. Boundary: avoid generic bride, horror doll, or explicit desire.", ontologyLevel: 4, risk: "medium", tags: ["android", "bride", "emotion_patch"] },
  { id: "courtroom_testimony_android", name: "法庭证人仿生人", nameEn: "Courtroom Witness Android", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是法庭证人仿生人。造型入口：证人席姿态、记忆读取端口、克制表情、编号手环和被质疑真实性的直视眼神。母题：记忆记录在法律场景里不再自动等于真相。张力：他/她要像证人，也像一件可被拆验的证据。视觉证据：法庭灯、数据线、宣誓手势、备份硬盘和旁听席投来的怀疑目光。边界：避免普通证人或司法机器人。", defEn: "First read: Courtroom Witness Android. Styling entry: witness-stand posture, memory-read port, restrained expression, serial wristband, and a gaze whose truth is questioned. Recorded memory does not automatically equal truth. Visual evidence: courtroom light, data cable, oath gesture, backup drive, and suspicious audience looks. Boundary: avoid generic witness or legal robot.", ontologyLevel: 4, tags: ["witness", "android", "court"] },
  { id: "garden_companion_robot", name: "花园陪伴机器人", nameEn: "Garden Companion Robot", group: "D. 仿生人 / 合成人社会", groupEn: "D. Android / Synthetic Society", def: "第一识别是花园陪伴机器人。造型入口：柔性外壳、园艺围裙、花粉痕迹、温和传感眼和在人类孤独中培养植物的缓慢陪伴。母题：护理、园艺和陪伴被压进一个柔软机器身体。张力：它要有服务功能和情感距离，不能只是可爱花园机器人。视觉证据：修枝剪、土壤传感器、花盆标签、软手套和等待主人说话的静止。边界：避免玩具机器人或普通园丁。", defEn: "First read: Garden Companion Robot. Styling entry: soft shell, gardening apron, pollen traces, gentle sensor eyes, and slow companionship growing plants inside human loneliness. Care, gardening, and company share one machine body. Visual evidence: pruning shears, soil sensor, pot labels, soft gloves, and stillness waiting for speech. Boundary: avoid toy robot or generic gardener.", ontologyLevel: 4, tags: ["companion_robot", "garden", "care"] },

  { id: "algorithm_temple_ceo", name: "算法神殿CEO", nameEn: "Algorithm-Temple CEO", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是算法神殿CEO。造型入口：极简西装、数据圣徽、发布会台阶、冷光徽章和把企业权威包装成神谕的平稳手势。母题：算法公司把商业决策转译成不可质疑的启示。张力：他/她不是宗教领袖，而是把信仰话术用于数据治理的企业统治者。视觉证据：透明演示屏、权限牌、审计黑箱、无标志领针和台下仰视灯光。边界：避免普通CEO、抽象AI神或赛博祭司。", defEn: "First read: Algorithm-Temple CEO. Styling entry: minimal suit, data sigil, keynote steps, cold badge, and smooth gestures packaging corporate authority as oracle. Algorithmic business becomes unquestioned revelation. Visual evidence: transparent presentation screen, access badge, audit black box, logo-free pin, and upward stage light. Boundary: avoid generic CEO, abstract AI god, or cyber priest.", ontologyLevel: 3, tags: ["ai", "ceo", "oracle"] },
  { id: "data_confession_priest", name: "数据忏悔神父", nameEn: "Data-Confession Priest", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是数据忏悔神父。造型入口：白色耳机、隐私屏、忏悔舱终端、柔和职业笑和替算法收集罪感的倾听姿势。母题：个人隐私被仪式化成可分析的数据供词。张力：温和感必须带平台采集压力，而不是传统神职。视觉证据：声纹波形、匿名编号、半透明隔间、记录灯和合上的双手。边界：避免普通神父、心理咨询师或数据客服。", defEn: "First read: Data-Confession Priest. Styling entry: white headset, privacy screen, confession-booth terminal, soft professional smile, and listening posture collecting guilt for algorithms. Privacy becomes analyzable confession. Visual evidence: voice waveform, anonymous code, translucent booth, recording light, and folded hands. Boundary: avoid generic priest, therapist, or data support agent.", ontologyLevel: 3, tags: ["data", "priest", "confession"] },
  { id: "predictive_policing_analyst", name: "预测警务分析师", nameEn: "Predictive-Policing Analyst", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是预测警务分析师。造型入口：地图墙、风险色块、无表情眼镜、执法权限牌和把未来犯罪提前归档的冷静坐姿。母题：算法把可能性变成制度暴力。张力：他/她的危险来自屏幕后的分类，而不是武器。视觉证据：热区地图、嫌疑评分、咖啡冷渍、审查表和不看当事人的眼。边界：避免普通数据分析师或警探。", defEn: "First read: Predictive-Policing Analyst. Styling entry: map wall, risk color blocks, expressionless glasses, enforcement badge, and seated calm filing future crime early. Algorithm turns possibility into institutional violence. Visual evidence: heat map, suspicion score, cold coffee stain, review form, and eyes avoiding the subject. Boundary: avoid generic analyst or detective.", ontologyLevel: 3, risk: "medium", tags: ["policing", "analyst", "prediction"] },
  { id: "cloud_memory_funeral_director", name: "云端记忆葬仪师", nameEn: "Cloud-Memory Funeral Director", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是云端记忆葬仪师。造型入口：黑色正装、纪念屏幕、备份钥匙、干净白手套和管理死者数字残影的安静职业礼仪。母题：死亡后的数据被整理、销售和告别。张力：哀悼要和服务流程并存，不能变成鬼故事。视觉证据：数字灵牌、登录权限、花束、云端存储盒和低声说明的侧身。边界：避免普通葬仪师或灵媒。", defEn: "First read: Cloud-Memory Funeral Director. Styling entry: black formalwear, memorial screen, backup key, clean white gloves, and quiet etiquette managing digital remains. Death data is organized, sold, and mourned. Visual evidence: digital memorial tablet, login access, flowers, cloud-storage box, and low explanatory posture. Boundary: avoid generic funeral director or medium.", ontologyLevel: 3, risk: "medium", tags: ["memory", "funeral", "cloud"] },
  { id: "machine_learning_monk", name: "机器学习修士", nameEn: "Machine-Learning Monk", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是机器学习修士。造型入口：灰袍、训练数据卷轴、沉默规则、标注手套和把模型训练当成苦修的低头专注。母题：数据劳动被伪装成精神纪律。张力：修行感必须落在标注、清洗、训练和重复动作上。视觉证据：标签纸、代码经卷、服务器冷光、磨损袖口和不抬头的长时间坐姿。边界：避免普通程序员或禅意僧侣。", defEn: "First read: Machine-Learning Monk. Styling entry: grey robe, training-data scrolls, silence rule, annotation gloves, and bowed focus treating model training as ascetic practice. Data labor wears spiritual discipline. Visual evidence: labels, code scrolls, server glow, worn cuffs, and long seated posture. Boundary: avoid generic programmer or Zen monk.", ontologyLevel: 3, tags: ["machine_learning", "monk", "data"] },
  { id: "platform_moderation_saint", name: "平台审核圣徒", nameEn: "Platform Moderation Saint", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是平台审核圣徒。造型入口：护目镜、删改手套、疲惫圣像感、工牌和替平台吸收污染图像后的僵硬肩颈。母题：内容审核被神圣化为替众人承受不可见伤害。张力：圣徒感要来自劳动创伤和屏幕制度，不是传统宗教光辉。视觉证据：模糊屏幕、红色标注、眼药水、隔音耳机和僵住的手腕。边界：避免普通客服、殉道图像或血腥化。", defEn: "First read: Platform Moderation Saint. Styling entry: goggles, redaction gloves, tired saintly aura, work badge, and stiff shoulders after absorbing platform pollution. Content moderation becomes invisible sacrifice. Visual evidence: blurred screens, red marks, eye drops, isolation headset, and frozen wrist. Boundary: avoid generic support worker, martyr painting, or gore.", ontologyLevel: 3, risk: "medium", tags: ["moderation", "platform", "saint"] },
  { id: "ai_hr_recruiter", name: "AI人事招募官", nameEn: "AI HR Recruiter", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是AI人事招募官。造型入口：无菌职业装、面试平板、评分模型界面、标准微笑和把人格转换成雇佣概率的手指滑动。母题：职场入口被算法化为温柔筛选。张力：亲切必须带冷冰冰的排除机制。视觉证据：候选人分数、玻璃会议室、权限胸牌、自动回复模板和停在淘汰键上的手。边界：避免普通HR或机器人面试官。", defEn: "First read: AI HR Recruiter. Styling entry: sterile officewear, interview tablet, scoring interface, standard smile, and a finger converting personality into hiring probability. Workplace entry becomes gentle algorithmic exclusion. Visual evidence: candidate scores, glass meeting room, access badge, auto-reply template, and hand paused over rejection. Boundary: avoid generic HR or robot interviewer.", ontologyLevel: 2, tags: ["ai_hr", "recruiter", "corporate"] },
  { id: "quantum_prophecy_trader", name: "量子预言交易员", nameEn: "Quantum-Prophecy Trader", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是量子预言交易员。造型入口：透明屏、祈祷般的手势、市场曲线、细窄西装和把预测当成神谕买卖的专注眼。母题：金融预测和神秘预言在高速市场里重合。张力：玄学感必须被交易终端、风险模型和手势控制住。视觉证据：多重价格线、护身符式密钥、耳内报价、冷汗和压在桌面的指尖。边界：避免普通交易员或玄学法师。", defEn: "First read: Quantum-Prophecy Trader. Styling entry: transparent screens, prayer-like hands, market curves, narrow suit, and focused eyes trading prediction as oracle. Finance and prophecy overlap in high-speed markets. Visual evidence: layered price lines, talisman-like key, in-ear quote, cold sweat, and fingertips pressed to desk. Boundary: avoid generic trader or mystic mage.", ontologyLevel: 4, risk: "medium", tags: ["quantum", "trader", "prophecy"] },
  { id: "black_box_auditor", name: "黑箱审计员", nameEn: "Black-Box Auditor", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是黑箱审计员。造型入口：灰西装、封存硬盘、审计标记、无装饰文件夹和面对不可解释系统时的冷静怀疑。母题：权力越自动化，越需要有人检查它的盲区。张力：他/她的造型应低调、干燥、专业，像随时能让系统停机。视觉证据：封条、日志屏、红笔批注、防篡改箱和微皱眉心。边界：避免普通会计或黑客。", defEn: "First read: Black-Box Auditor. Styling entry: grey suit, sealed drives, audit marks, plain folder, and calm suspicion before unexplainable systems. Automated power requires someone to inspect blind spots. Visual evidence: seals, log screen, red annotations, tamper-proof case, and slight brow tension. Boundary: avoid generic accountant or hacker.", ontologyLevel: 3, tags: ["auditor", "black_box", "ai"] },
  { id: "synthetic_afterlife_consultant", name: "合成来世顾问", nameEn: "Synthetic Afterlife Consultant", group: "E. AI企业 / 数据神职", groupEn: "E. AI Corporate / Data Clergy", def: "第一识别是合成来世顾问。造型入口：咨询室西装、数字灵牌、微笑话术、柔和屏幕光和售卖上传后生命的过分体贴。母题：来世被公司包装成订阅服务。张力：温柔服务必须带骗局边缘和技术合法性。视觉证据：套餐目录、亲属照片、云端合同、安抚手势和不完全真诚的眼神。边界：避免普通销售、灵媒或科幻骗子脸谱。", defEn: "First read: Synthetic Afterlife Consultant. Styling entry: counseling suit, digital memorial tablet, scripted smile, soft screen light, and excessive care selling uploaded life. Afterlife becomes a subscription product. Visual evidence: package brochure, family photo, cloud contract, soothing gesture, and not-quite-sincere gaze. Boundary: avoid generic salesperson, medium, or cartoon sci-fi scammer.", ontologyLevel: 4, risk: "medium", tags: ["afterlife", "consultant", "ai"] },

  { id: "academy_mecha_cadet", name: "机甲学院新兵", nameEn: "Mecha Academy Cadet", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是机甲学院新兵。造型入口：训练服、编号徽章、颈部接口、还没磨合好的驾驶手套和把青春献给巨型机器的紧张站姿。母题：军校把少年身体预先适配驾驶舱。张力：稚嫩与制度化战争要同时可见。视觉证据：模拟舱灯、成绩贴纸、护颈、紧咬嘴唇和过新的靴子。边界：避免普通学生、英勇机甲主角或偶像制服。", defEn: "First read: Mecha Academy Cadet. Styling entry: training suit, serial badge, neck interface, stiff new pilot gloves, and tense youth given to giant machines. The academy adapts young bodies to cockpits. Visual evidence: simulator light, score stickers, neck guard, bitten lip, and too-new boots. Boundary: avoid generic student, heroic mecha lead, or idol uniform.", ontologyLevel: 3, tags: ["mecha", "cadet", "academy"] },
  { id: "ace_mecha_pilot", name: "王牌机甲驾驶员", nameEn: "Ace Mecha Pilot", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是王牌机甲驾驶员。造型入口：紧身驾驶服、战绩涂装、疲惫眼神、手套磨损和被神话化的单兵战功压出的孤立气质。母题：驾驶员身体成为宣传机器的战绩界面。张力：英雄感必须混着损耗、创伤和不被允许失败的压力。视觉证据：击坠标记、氧气管、旧伤贴片、头盔夹在臂弯和不看镜头的眼。边界：避免普通飞行员或炫酷战士。", defEn: "First read: Ace Mecha Pilot. Styling entry: tight pilot suit, victory markings, tired gaze, worn gloves, and isolation from mythologized combat record. The pilot body becomes propaganda interface. Visual evidence: kill marks, oxygen hose, old injury patches, helmet under arm, and eyes off camera. Boundary: avoid generic pilot or cool warrior.", ontologyLevel: 3, risk: "medium", tags: ["ace", "mecha", "pilot"] },
  { id: "maintenance_bay_girl", name: "机库维修少女", nameEn: "Maintenance-Bay Girl", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是机库维修少女。造型入口：油污背心、扳手、吊装带、短发沾灰和比驾驶员更懂机器脾气的熟练眼神。母题：机甲世界里真正稳定战场的是维修劳动。张力：她不能只是可爱技师，身体要有长期机库生活的划痕和力量。视觉证据：零件箱、液压臂、手肘油渍、耳塞和蹲在巨大脚部装甲旁的姿态。边界：避免维修萌妹或普通机械师。", defEn: "First read: Maintenance-Bay Girl. Styling entry: oily tank, wrench, hoist straps, dusty short hair, and skilled eyes knowing the machine better than pilots. Maintenance labor stabilizes the battlefield. Visual evidence: parts box, hydraulic arm, elbow oil, earplugs, and a crouch beside giant foot armor. Boundary: avoid cute mechanic trope or generic technician.", ontologyLevel: 2, tags: ["maintenance", "hangar", "mecha"] },
  { id: "disabled_veteran_pilot", name: "退役伤残驾驶员", nameEn: "Disabled Veteran Pilot", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是退役伤残驾驶员。造型入口：旧驾驶夹克、义肢、勋章、被驾驶舱安全带留下的旧压痕和仍会被机械声召回的身体记忆。母题：战争退场后，驾驶系统还留在身体里。张力：伤残不能只是悲情，要带经验、尊严和不再适配新机型的落差。视觉证据：旧头盔、药盒、训练照片、磨损义肢接口和听见警报时抬头的反射。边界：避免普通老兵或悲惨病人。", defEn: "First read: Disabled Veteran Pilot. Styling entry: old pilot jacket, prosthetic limb, medals, cockpit-strap marks, and body memory still called by machine sound. War remains after retirement. Visual evidence: old helmet, medication box, training photo, worn prosthetic socket, and reflexive lift of the head at alarms. Boundary: avoid generic veteran or tragic patient.", ontologyLevel: 3, risk: "medium", tags: ["veteran", "pilot", "prosthetic"] },
  { id: "idol_mecha_pilot", name: "偶像机甲驾驶员", nameEn: "Idol Mecha Pilot", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是偶像机甲驾驶员。造型入口：舞台制服、驾驶接口、粉丝贴纸、直播镜头感和把战争包装成娱乐节目的过亮笑容。母题：军事机器被偶像工业重新包装给公众观看。张力：可爱、宣传和死亡风险必须挤在同一套衣服里。视觉证据：应援贴在头盔上、机体签名、耳返、战绩直播屏和练习笑容。边界：避免普通偶像或热血驾驶员。", defEn: "First read: Idol Mecha Pilot. Styling entry: stage uniform, pilot interface, fan stickers, livestream awareness, and a too-bright smile packaging war as entertainment. Military machinery is made watchable by idol industry. Visual evidence: fan stickers on helmet, signed machine parts, in-ear monitor, combat stream screen, and practiced smile. Boundary: avoid generic idol or hot-blooded pilot.", ontologyLevel: 3, risk: "medium", tags: ["idol", "mecha", "pilot"] },
  { id: "bio_sync_pilot", name: "生体同步驾驶员", nameEn: "Bio-Sync Pilot", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是生体同步驾驶员。造型入口：生物接口服、脊背导线、眩晕表情、皮肤下的反馈光和与机器共享神经痛感的危险松弛。母题：驾驶不再是操作，而是让身体和机体互相侵入。张力：高风险要通过不适、同步痕迹和依赖关系表现。视觉证据：背部插槽、心率屏、肌肉抽动、固定床带和半闭眼呼吸。边界：避免普通驾驶服或怪物化机甲。", defEn: "First read: Bio-Sync Pilot. Styling entry: bio-interface suit, spine cables, dizzy expression, subdermal feedback glow, and dangerous looseness from sharing neural pain with machine. Piloting becomes bodily intrusion. Visual evidence: back sockets, heart-rate screen, muscle twitch, restraint straps, and half-closed breathing. Boundary: avoid generic pilot suit or monster mecha.", ontologyLevel: 4, risk: "high", tags: ["bio_sync", "pilot", "neural"] },
  { id: "frontline_mecha_medic", name: "前线机甲医疗兵", nameEn: "Frontline Mecha Medic", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是前线机甲医疗兵。造型入口：急救外骨骼、医疗标记、机械担架、沾灰面罩和在巨型战场回收身体的快速判断。母题：医疗职责被放大到钢铁废墟和驾驶舱残骸之间。张力：他/她不是医生也不是士兵，而是在机器尺度里救人。视觉证据：红十字装甲片、止血喷罐、拖拽钩、碎甲背景和蹲下检查的动作。边界：避免普通军医或战术机甲兵。", defEn: "First read: Frontline Mecha Medic. Styling entry: medical exoskeleton, medic marks, mechanical stretcher, dusty visor, and quick judgment recovering bodies on giant battlefields. Care happens among steel wreckage and cockpits. Visual evidence: medical armor plates, clotting spray, drag hook, broken armor background, and crouched inspection. Boundary: avoid generic combat medic or tactical mecha soldier.", ontologyLevel: 3, risk: "medium", tags: ["mecha", "medic", "frontline"] },
  { id: "aristocratic_mecha_heir", name: "贵族机甲继承人", nameEn: "Aristocratic Mecha Heir", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是贵族机甲继承人。造型入口：家徽驾驶服、礼仪披风、专属机编号、干净手套和把血统转成战争资格的冷静站姿。母题：巨型机器成为继承秩序的新骑士制度。张力：贵族礼制和军事接口要彼此绑定，而不是各自装饰。视觉证据：机体纹章、授勋带、驾驶舱钥印、家族色内衬和不急于证明自己的眼。边界：避免普通贵族或热血机甲少年。", defEn: "First read: Aristocratic Mecha Heir. Styling entry: heraldic pilot suit, ceremonial cape, personal machine serial, clean gloves, and calm posture turning bloodline into war qualification. Giant machines become a new chivalric inheritance system. Visual evidence: machine crest, decoration ribbon, cockpit key seal, family-color lining, and unhurried gaze. Boundary: avoid generic noble or hot-blooded mecha youth.", ontologyLevel: 3, tags: ["aristocracy", "mecha", "heir"] },
  { id: "underground_mecha_duelist", name: "地下机甲决斗者", nameEn: "Underground Mecha Duelist", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是地下机甲决斗者。造型入口：非法驾驶服、赔率贴纸、维修疤痕、口袋里的下注票和把巨型机器当街头拳台的挑衅姿态。母题：正规战争技术被拖进地下赌博和荣誉争斗。张力：街头感要依附机体维修、赔率和违规驾驶。视觉证据：临时焊点、涂改编号、观众围栏、破损护目镜和挑眉挑衅。边界：避免普通拳手或炫酷机甲驾驶员。", defEn: "First read: Underground Mecha Duelist. Styling entry: illegal pilot suit, betting stickers, repair scars, wager slips, and a taunting posture using giant machines as street ring. War technology enters underground gambling. Visual evidence: temporary welds, altered serial, crowd barrier, broken goggles, and raised-brow challenge. Boundary: avoid generic fighter or cool pilot.", ontologyLevel: 3, risk: "medium", tags: ["underground", "duelist", "mecha"] },
  { id: "remote_swarm_pilot", name: "远程蜂群驾驶员", nameEn: "Remote Swarm Pilot", group: "F. 机甲 / 驾驶员体系", groupEn: "F. Mecha / Pilot System", def: "第一识别是远程蜂群驾驶员。造型入口：控制椅、神经头盔、微型机群徽记、苍白久坐皮肤和把身体留在后方的战争疏离感。母题：战斗被拆成许多无人机视角和一个静止身体。张力：他/她越不动，越要显出远处杀伤正在发生。视觉证据：多屏界面、手指抽动、眼球追踪灯、营养管和蜂群轨迹图。边界：避免普通无人机操作员或机甲驾驶员。", defEn: "First read: Remote Swarm Pilot. Styling entry: control chair, neural helmet, swarm insignia, pale seated skin, and war detachment from leaving the body behind. Combat is split into many drone views and one still body. Visual evidence: multi-screen interface, finger twitches, eye-tracking lights, nutrition tube, and swarm path map. Boundary: avoid generic drone operator or mecha pilot.", ontologyLevel: 4, risk: "medium", tags: ["swarm", "pilot", "remote"] },

  { id: "posthuman_couture_elite", name: "后人类高定精英", nameEn: "Posthuman Couture Elite", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是后人类高定精英。造型入口：透明材料、优化骨相、医疗珠宝、冷淡表情和把身体作为阶层产品展示的无声优越感。母题：升级身体成为奢侈品和准入门槛。张力：美必须带资产属性、医疗维护和社会距离。视觉证据：器官认证标签、皮下光泽、定制接缝、私人诊所痕迹和不与人同框的站位。边界：避免普通高定模特或无代价完美身体。", defEn: "First read: Posthuman Couture Elite. Styling entry: transparent materials, optimized bone structure, medical jewelry, cold expression, and silent superiority displaying the body as class product. Upgrade becomes luxury access. Visual evidence: organ-cert tags, subdermal sheen, custom seams, private-clinic traces, and isolated stance. Boundary: avoid generic couture model or perfect body without cost.", ontologyLevel: 5, risk: "high", tags: ["posthuman", "couture", "elite"] },
  { id: "longevity_billionaire", name: "长生富豪", nameEn: "Longevity Billionaire", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是长生富豪。造型入口：年轻化皮肤、医疗珠宝、私人诊所手环、克制运动服和把死亡推迟成资产管理的安静疲惫。母题：寿命被财富拆成疗程、排队和续费。张力：他/她要显得年轻，却不能像真正年轻人。视觉证据：血液监测贴片、冷藏药盒、私人电梯、细微老眼神和过度保养的手。边界：避免普通富豪、吸血鬼或美容广告。", defEn: "First read: Longevity Billionaire. Styling entry: rejuvenated skin, medical jewelry, private-clinic band, restrained activewear, and quiet fatigue treating death delay as asset management. Lifespan becomes treatment and renewal. Visual evidence: blood-monitor patch, chilled medication case, private elevator, subtly old eyes, and over-maintained hands. Boundary: avoid generic billionaire, vampire, or beauty ad.", ontologyLevel: 4, risk: "medium", tags: ["longevity", "billionaire", "elite"] },
  { id: "memory_edited_socialite", name: "记忆编辑名媛", nameEn: "Memory-Edited Socialite", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是记忆编辑名媛。造型入口：完美社交笑容、记忆备份饰品、短暂空白的眼、晚宴礼服和被剪辑过的人格连贯性。母题：社交身份靠删除尴尬、创伤和旧关系维持光滑。张力：优雅下必须有记忆断点。视觉证据：颈侧备份坠、表情延迟、宾客名单、香槟杯和突然停顿的手。边界：避免普通名媛或失忆剧情角色。", defEn: "First read: Memory-Edited Socialite. Styling entry: perfect social smile, memory-backup ornament, blank eyes for a second, evening dress, and edited personality continuity. Social status is kept smooth by deleting embarrassment and trauma. Visual evidence: neck backup pendant, expression delay, guest list, champagne glass, and sudden hand pause. Boundary: avoid generic socialite or amnesia character.", ontologyLevel: 4, risk: "medium", tags: ["memory_edit", "socialite", "posthuman"] },
  { id: "synthetic_organ_athlete", name: "合成器官运动员", nameEn: "Synthetic-Organ Athlete", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是合成器官运动员。造型入口：运动压缩服、器官认证标签、体能数据贴片、干净爆发力和被体育公平边界围住的身体。母题：竞技优势被医疗合法性重新定义。张力：他/她要像运动员，也像一份争议中的检测报告。视觉证据：胸腔扫描图、赛场号码、检测腕带、肌肉线条和被记者围住的沉默。边界：避免普通健身角色或机械义体战士。", defEn: "First read: Synthetic-Organ Athlete. Styling entry: compression sportswear, organ-certification tags, performance patches, clean explosive power, and a body trapped by fairness debates. Athletic advantage is redefined by medical legality. Visual evidence: chest scan, race number, test wristband, muscle lines, and silence before reporters. Boundary: avoid generic fitness figure or prosthetic warrior.", ontologyLevel: 4, risk: "medium", tags: ["athlete", "synthetic_organ", "sport"] },
  { id: "designer_baby_heir", name: "设计婴儿继承人", nameEn: "Designer-Baby Heir", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是设计婴儿继承人。造型入口：精确五官、家族基因纹章、贵族校服、过分洁净皮肤和从出生前就被规划的冷静少年感。母题：继承权提前写进基因选择。张力：完美必须带计划性和不自由，而不是漂亮孩子。视觉证据：基因证书、校徽、保姆距离、健康监测贴和被训练出的坐姿。边界：避免萌化儿童、普通贵族学生或实验室婴儿。", defEn: "First read: Designer-Baby Heir. Styling entry: precise features, family gene heraldry, elite school uniform, overly clean skin, and calm youth planned before birth. Succession is written into selection. Visual evidence: gene certificate, school crest, caregiver distance, health patch, and trained seated posture. Boundary: avoid cute child, generic noble student, or lab infant.", ontologyLevel: 4, tags: ["designer_baby", "heir", "elite"] },
  { id: "uploaded_mind_widow", name: "上传意识寡妇", nameEn: "Uploaded-Mind Widow", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是上传意识寡妇。造型入口：黑色服装、云端戒指、空壳终端、疲惫妆容和哀悼一个仍会回应的亡者时的犹豫手指。母题：死亡被数字备份打断，哀悼失去边界。张力：她不是普通寡妇，悲伤对象同时缺席又在线。视觉证据：聊天屏、纪念头像、婚戒接口、黑纱和迟迟不按下通话键的手。边界：避免鬼魂恋人或普通丧偶角色。", defEn: "First read: Uploaded-Mind Widow. Styling entry: black clothing, cloud ring, empty terminal, tired makeup, and hesitant fingers mourning a dead person who still answers. Backup interrupts death and grief. Visual evidence: chat screen, memorial avatar, ring port, black veil, and hand unable to press call. Boundary: avoid ghost lover or generic widow.", ontologyLevel: 5, risk: "high", tags: ["uploaded_mind", "widow", "grief"] },
  { id: "gene_optimized_soldier", name: "基因优化士兵", nameEn: "Gene-Optimized Soldier", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是基因优化士兵。造型入口：规训肌肉、医疗编号、无痛表情、贴身作战服和被军队设计出来的功能性身体。母题：士兵不再只是训练结果，而是设计结果。张力：强壮要带非个人化和制度所有权。视觉证据：基因批次码、药物泵、干净伤口、队列姿态和不自然稳定的呼吸。边界：避免普通特种兵或超级英雄。", defEn: "First read: Gene-Optimized Soldier. Styling entry: disciplined muscle, medical code, painless expression, fitted combat suit, and body function designed by the military. The soldier is designed, not merely trained. Visual evidence: gene batch code, drug pump, clean wounds, formation posture, and unnaturally steady breathing. Boundary: avoid generic special forces or superhero.", ontologyLevel: 4, risk: "medium", tags: ["gene_optimized", "soldier", "military"] },
  { id: "limb_subscription_worker", name: "义肢订阅工人", nameEn: "Limb-Subscription Worker", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是义肢订阅工人。造型入口：可拆卸义肢、账单贴纸、工作服、平台催缴提示和身体功能被租赁后的阶级压力。母题：劳动能力变成按月付费的身体部件。张力：科技不能显得解放，必须带欠费、磨损和替换焦虑。视觉证据：义肢接口、二维码账单、工牌、备用螺丝和护住接口的手。边界：避免酷义肢、普通工人或励志残障叙事。", defEn: "First read: Limb-Subscription Worker. Styling entry: detachable prosthetic limb, billing stickers, workwear, platform payment warning, and class pressure from rented body function. Labor ability becomes monthly hardware. Visual evidence: limb socket, QR bill, work badge, spare screws, and hand protecting the interface. Boundary: avoid cool prosthetic style, generic worker, or inspirational disability trope.", ontologyLevel: 4, risk: "medium", tags: ["prosthetic", "subscription", "worker"] },
  { id: "emotion_suppressed_diplomat", name: "情绪抑制外交官", nameEn: "Emotion-Suppressed Diplomat", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是情绪抑制外交官。造型入口：无波表情、颈侧药泵、礼服、谈判文件和把感情调低以服务协议的稳定眼神。母题：政治身体通过药物和接口控制情绪幅度。张力：优雅来自被压住的反应，而不是天生冷酷。视觉证据：药泵灯、签字笔、压平衣领、翻译耳机和几乎不动的嘴角。边界：避免普通外交官或冷面反派。", defEn: "First read: Emotion-Suppressed Diplomat. Styling entry: flat expression, neck drug pump, formal dress, negotiation files, and steady eyes with emotions turned down for protocol. Political body regulates affect through medicine and interface. Visual evidence: pump light, signing pen, flattened collar, interpreter earpiece, and nearly still mouth. Boundary: avoid generic diplomat or cold villain.", ontologyLevel: 4, tags: ["emotion_suppression", "diplomat", "posthuman"] },
  { id: "transhuman_cult_leader", name: "超人类教团领袖", nameEn: "Transhuman Cult Leader", group: "G. 后人类 / 身体升级", groupEn: "G. Posthuman / Body Upgrade", def: "第一识别是超人类教团领袖。造型入口：改造圣痕、透明长袍、追随者目光、升级接口和把身体优化说成救赎的平静微笑。母题：超人类技术被包装成宗教出路。张力：神圣感必须和医疗改造、阶层操控、追随者依赖纠缠。视觉证据：皮下线路、讲坛、捐献名单、发光疤痕和向外张开的双手。边界：避免普通邪教、机器人教主或纯神棍。", defEn: "First read: Transhuman Cult Leader. Styling entry: modified stigmata, transparent robe, follower gaze, upgrade ports, and calm smile preaching optimization as salvation. Transhuman technology becomes religious escape. Visual evidence: subdermal lines, lectern, donation list, glowing scars, and open hands. Boundary: avoid generic cult leader, robot preacher, or charlatan.", ontologyLevel: 5, risk: "high", tags: ["transhuman", "cult", "leader"] },

  { id: "space_age_stewardess", name: "太空时代空姐", nameEn: "Space-Age Stewardess", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是太空时代空姐。造型入口：圆形头盔、亮面制服、短手套、固定微笑和上世纪想象中轨道旅行的服务姿态。母题：旧未来把宇宙旅行想象成航空消费升级。张力：她的未来感要乐观、商品化、展览式，不要变成硬科幻乘务员。视觉证据：铬色餐车、圆窗、浅色塑料扣、登机牌和广告海报式站姿。边界：避免现代空姐或真实宇航服。", defEn: "First read: Space-Age Stewardess. Styling entry: bubble helmet, glossy uniform, short gloves, fixed smile, and service posture from last centurys orbital fantasy. Space travel is imagined as upgraded air travel. Visual evidence: chrome cart, round window, pale plastic buckle, boarding pass, and advertisement-poster stance. Boundary: avoid modern flight attendant or real spacesuit.", ontologyLevel: 2, eras: ["modern", "near_future", "timeless"], tags: ["space_age", "stewardess", "retro"] },
  { id: "atomic_diner_waitress", name: "原子餐厅女侍", nameEn: "Atomic Diner Waitress", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是原子餐厅女侍。造型入口：铬色托盘、圆形霓虹、复古制服、泡泡字胸牌和把未来当成家常消费出售的明亮笑容。母题：原子时代乐观主义落进餐厅服务。张力：未来感应当像商品广告和日常便利，不要变成现代赛博。视觉证据：弧形吧台、奶昔杯、火箭菜单、亮面地砖和轻快递餐手势。边界：避免普通复古餐厅或科幻酒吧。", defEn: "First read: Atomic Diner Waitress. Styling entry: chrome tray, round neon, retro uniform, bubble-letter name tag, and bright smile selling future as daily consumption. Atomic optimism enters diner service. Visual evidence: curved counter, milkshake glass, rocket menu, glossy tiles, and quick serving gesture. Boundary: avoid generic retro diner or sci-fi bar.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["atomic", "diner", "retro"] },
  { id: "raygun_private_eye", name: "射线枪私家侦探", nameEn: "Raygun Private Eye", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是射线枪私家侦探。造型入口：风衣、铬色射线枪、圆形仪表、帽檐阴影和把黑色电影套进太空时代的怀疑眼神。母题：侦探类型片被旧未来道具轻微扭曲。张力：他/她要像老派私探，但证据来自过时的未来机器。视觉证据：射线枪皮套、烟雾灯、复古通讯器、案件照片和靠在模型城市旁的姿态。边界：避免现代枪手或硬科幻探员。", defEn: "First read: Raygun Private Eye. Styling entry: trench coat, chrome raygun, round dials, hat shadow, and noir suspicion folded into space-age fantasy. Detective genre is bent by old-future props. Visual evidence: raygun holster, smoky light, retro communicator, case photos, and leaning near model city. Boundary: avoid modern gunman or hard sci-fi agent.", ontologyLevel: 2, eras: ["modern", "timeless"], risk: "medium", tags: ["raygun", "detective", "retrofuture"] },
  { id: "bubble_helmet_pop_princess", name: "泡泡头盔流行公主", nameEn: "Bubble-Helmet Pop Princess", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是泡泡头盔流行公主。造型入口：亮色迷你裙、透明头盔、唱片封面姿态、夸张睫毛和可爱旧未来的塑料光泽。母题：太空时代被流行音乐包装成少女消费图像。张力：可爱要带年代感和展示性，不要变成现代偶像。视觉证据：星星贴纸、圆形麦克风、亮面靴、粉彩背景和手托头盔的姿势。边界：避免普通流行歌手或科幻公主。", defEn: "First read: Bubble-Helmet Pop Princess. Styling entry: bright miniskirt, transparent helmet, record-cover pose, dramatic lashes, and plastic shine of cute old futurity. Space age becomes pop consumer image. Visual evidence: star stickers, round microphone, glossy boots, pastel backdrop, and hands holding the helmet. Boundary: avoid generic pop singer or sci-fi princess.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["pop", "bubble_helmet", "retro"] },
  { id: "world_fair_inventor", name: "世界博览会发明家", nameEn: "World-Fair Inventor", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是世界博览会发明家。造型入口：白西装、圆顶机器、模型城市、夸张演示手势和向公众展示美好未来的自信笑。母题：未来被做成展馆里的消费承诺。张力：发明感要公开、乐观、表演化，而不是孤独科学家。视觉证据：展台灯、说明牌、圆形按钮、观众剪影和指向模型的手杖。边界：避免现代创业者或疯狂博士。", defEn: "First read: World-Fair Inventor. Styling entry: white suit, domed machine, model city, theatrical demo gesture, and confident smile presenting a better future. Future becomes exhibition promise. Visual evidence: booth lights, explanation placard, round buttons, audience silhouettes, and cane pointing at the model. Boundary: avoid modern founder or mad scientist.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["world_fair", "inventor", "retro"] },
  { id: "retro_robot_repair_boy", name: "复古机器人维修少年", nameEn: "Retro Robot Repair Boy", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是复古机器人维修少年。造型入口：背带裤、工具箱、圆眼机器人、家庭车库灯和把未来玩具当朋友修理的认真表情。母题：旧未来的机器人仍像家用电器和儿童伙伴。张力：童真要被工具、零件和年代广告感支撑。视觉证据：圆形螺丝、说明书、油布、车库架子和蹲在机器人脚边的姿势。边界：避免现代机器人少年或真实儿童冒险片。", defEn: "First read: Retro Robot Repair Boy. Styling entry: overalls, toolbox, round-eyed robot, garage light, and serious expression repairing a future toy friend. Old-future robots feel like appliances and companions. Visual evidence: round screws, manual, oil cloth, garage shelves, and crouch beside robot feet. Boundary: avoid modern robot kid or child adventure film.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["robot", "repair", "retro"] },
  { id: "chrome_lounge_singer", name: "铬色太空酒廊歌手", nameEn: "Chrome Space-Lounge Singer", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是铬色太空酒廊歌手。造型入口：银色礼服、老式麦克风、星际酒廊、卷发光泽和把宇宙唱成爵士夜的慵懒站姿。母题：太空旅行被想象成夜生活和消费优雅。张力：她/他要像复古酒廊明星，不是未来歌姬。视觉证据：圆形舞台、铬色吧台、鸡尾酒杯、星图装饰和半闭眼唱腔。边界：避免现代夜店歌手或科幻偶像。", defEn: "First read: Chrome Space-Lounge Singer. Styling entry: silver gown, vintage microphone, interstellar lounge, glossy curls, and languid posture singing the cosmos as jazz night. Space travel becomes nightlife elegance. Visual evidence: round stage, chrome bar, cocktail glass, star-map decor, and half-closed singing eyes. Boundary: avoid modern club singer or sci-fi idol.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["lounge", "singer", "retro"] },
  { id: "utopian_city_planner", name: "乌托邦城市规划师", nameEn: "Utopian City Planner", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是乌托邦城市规划师。造型入口：建筑模型、圆形眼镜、浅色西装、干净指示棒和相信城市能解决一切的旧未来信念。母题：规划图纸把社会问题改写成弧形道路和透明穹顶。张力：乐观要略显天真，不能变成现代建筑师。视觉证据：模型社区、交通剖面图、蓝色网格、展览桌和俯身讲解姿态。边界：避免普通规划师或赛博城市设计师。", defEn: "First read: Utopian City Planner. Styling entry: architecture model, round glasses, pale suit, clean pointer, and old-future belief that cities can solve everything. Plans turn social problems into curves and domes. Visual evidence: model community, transit section, blue grid, exhibition table, and leaning explanation pose. Boundary: avoid generic planner or cyber city designer.", ontologyLevel: 1, eras: ["modern", "timeless"], tags: ["utopia", "planner", "city"] },
  { id: "retro_moon_pageant_queen", name: "复古月球选美皇后", nameEn: "Retro Moon Pageant Queen", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是复古月球选美皇后。造型入口：皇冠、月球绶带、亮片礼服、泡泡头盔和把太空殖民包装成选美盛典的灿烂笑容。母题：殖民宣传被娱乐化成美丽和荣誉。张力：她必须像宣传海报上的胜利符号，而不是普通选美佳丽。视觉证据：月面背景板、星形奖杯、白手套、过亮舞台灯和固定挥手姿态。边界：避免现代选美或真正月球宇航员。", defEn: "First read: Retro Moon Pageant Queen. Styling entry: crown, Moon sash, sequin gown, bubble helmet, and radiant smile packaging space colonization as pageant. Colonization propaganda becomes beauty and honor. Visual evidence: moon backdrop, star trophy, white gloves, bright stage lights, and fixed waving pose. Boundary: avoid modern pageant queen or real astronaut.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["pageant", "moon", "retro"] },
  { id: "analog_computer_oracle", name: "模拟计算机女预言家", nameEn: "Analog-Computer Oracle", group: "H. 复古未来 / 太空时代", groupEn: "H. Retrofuture / Space Age", def: "第一识别是模拟计算机女预言家。造型入口：穿孔纸带、白手套、巨大面板、整齐盘发和把运算结果说成命运的庄重表情。母题：早期计算机被展演成理性预言机器。张力：神秘感必须来自机械运算、纸带和仪表，不要变成魔法。视觉证据：灯泡矩阵、旋钮、打孔纸卷、读数夹板和轻触开关的手。边界：避免普通预言家或现代数据科学家。", defEn: "First read: Analog-Computer Oracle. Styling entry: punch tape, white gloves, giant panel, neat updo, and solemn expression speaking computation as destiny. Early computers become rational prophecy machines. Visual evidence: bulb matrix, dials, paper rolls, reading clipboard, and hand touching a switch. Boundary: avoid generic oracle or modern data scientist.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["analog", "oracle", "computer"] },

  { id: "dieselpunk_airship_captain", name: "柴油朋克飞艇船长", nameEn: "Dieselpunk Airship Captain", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是柴油朋克飞艇船长。造型入口：皮革长外套、飞行帽、铆钉甲板、厚重望远镜和在工业天空航线上指挥的粗粝站姿。母题：天空航行保留了海军、工厂和战争机器的重量。张力：浪漫冒险要被油污、噪声和机械制度压住。视觉证据：缆绳、黄铜仪表、风镜、铆钉手套和远处飞艇影。边界：避免普通飞行员或蒸汽朋克装饰。", defEn: "First read: Dieselpunk Airship Captain. Styling entry: leather long coat, flight cap, riveted deck, heavy spyglass, and rough command posture on industrial sky routes. Air travel keeps naval and factory weight. Visual evidence: cables, brass dials, goggles, riveted gloves, and airship silhouette. Boundary: avoid generic pilot or steampunk decoration.", ontologyLevel: 2, eras: industrialFutureEras, tags: ["dieselpunk", "airship", "captain"] },
  { id: "factory_war_engineer", name: "军工厂工程师", nameEn: "War-Factory Engineer", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是军工厂工程师。造型入口：油污工作服、蓝图、机械臂吊、钢尺和把战争拆成生产流程的冷硬眼神。母题：武器不是英雄道具，而是流水线、误差和加班的结果。张力：专业性要和工业暴力绑定。视觉证据：机床、编号零件、护目镜、烧伤袖口和盯着公差表的姿态。边界：避免普通工程师或战争军官。", defEn: "First read: War-Factory Engineer. Styling entry: oily coveralls, blueprints, crane arms, steel ruler, and hard eyes breaking war into production workflow. Weapons are made of assembly lines and tolerances. Visual evidence: machine tools, numbered parts, goggles, burned cuffs, and gaze fixed on tolerance charts. Boundary: avoid generic engineer or war officer.", ontologyLevel: 2, eras: industrialFutureEras, tags: ["factory", "engineer", "war"] },
  { id: "trench_radio_operator", name: "战壕无线电员", nameEn: "Trench Radio Operator", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是战壕无线电员。造型入口：厚重耳机、线圈背包、泥泞军装、紧贴耳机的手和把混乱战场连成声音网络的紧张专注。母题：通讯技术在泥土和炮火中维持战争神经。张力：他/她不是冲锋者，而是把身体贴在噪声里的节点。视觉证据：电线卷、信号本、泥点、防水布和听到断讯时僵住的眼。边界：避免普通士兵或无线电爱好者。", defEn: "First read: Trench Radio Operator. Styling entry: heavy headset, coil backpack, muddy uniform, hand pressed to ear, and tense focus linking battlefield chaos into sound network. Communication technology keeps war nerves alive. Visual evidence: cable roll, signal notebook, mud, tarp, and eyes freezing at lost signal. Boundary: avoid generic soldier or radio hobbyist.", ontologyLevel: 2, eras: ["industrial", "modern", "timeless"], risk: "medium", tags: ["radio", "trench", "operator"] },
  { id: "armored_train_conductor", name: "装甲列车乘务长", nameEn: "Armored-Train Conductor", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是装甲列车乘务长。造型入口：黑色制服、怀表、钢板车厢、票夹和在移动堡垒里维持秩序的严厉礼貌。母题：铁路服务和军事防护合成一套移动制度。张力：他/她像乘务长，也像守门军官。视觉证据：铆钉车门、车厢编号、煤烟、检票钳和挡住通道的站姿。边界：避免普通列车员或装甲士兵。", defEn: "First read: Armored-Train Conductor. Styling entry: black uniform, pocket watch, steel-plated carriage, ticket punch, and strict politeness maintaining order inside a moving fortress. Rail service fuses with military protection. Visual evidence: riveted door, carriage code, coal smoke, punch pliers, and blocking stance. Boundary: avoid generic conductor or armored soldier.", ontologyLevel: 2, eras: ["industrial", "modern", "timeless"], tags: ["armored_train", "conductor", "dieselpunk"] },
  { id: "oilfield_prophet_mechanic", name: "油田预言机械师", nameEn: "Oilfield Prophet Mechanic", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是油田预言机械师。造型入口：机油手套、井架、护目镜、沾油围巾和从机器噪声中听见未来的边缘神秘表情。母题：工业噪声被长期劳动者误读成预兆。张力：神秘感必须埋在油污、设备和疲劳里。视觉证据：钻井管、压力表、黑油痕、破笔记本和侧耳听机器的姿势。边界：避免普通机械师或真正神棍。", defEn: "First read: Oilfield Prophet Mechanic. Styling entry: oil gloves, derrick, goggles, stained scarf, and fringe-mystic expression hearing future inside machine noise. Prophecy grows from labor fatigue and engines. Visual evidence: drill pipe, pressure gauge, black oil marks, torn notebook, and head tilted to listen. Boundary: avoid generic mechanic or pure mystic.", ontologyLevel: 3, eras: industrialFutureEras, tags: ["oilfield", "mechanic", "prophet"] },
  { id: "pulp_rocket_commander", name: "纸浆科幻火箭指挥官", nameEn: "Pulp Rocket Commander", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是纸浆科幻火箭指挥官。造型入口：军帽、金属肩章、火箭徽章、夸张披风和旧杂志封面式向前指挥姿态。母题：早期科幻把军事冒险和火箭技术做成英雄图像。张力：夸张可以保留，但必须有印刷年代感和机械重量。视觉证据：铆钉火箭、红色警报灯、指挥手套、纸浆封面构图和粗黑阴影。边界：避免现代太空军官或超级英雄。", defEn: "First read: Pulp Rocket Commander. Styling entry: officer cap, metal epaulets, rocket badge, dramatic cape, and old magazine-cover command gesture. Early sci-fi turns rocket technology into heroic adventure. Visual evidence: riveted rocket, red alarm light, command gloves, pulp-cover framing, and heavy black shadows. Boundary: avoid modern space officer or superhero.", ontologyLevel: 2, eras: ["modern", "timeless"], tags: ["pulp", "rocket", "commander"] },
  { id: "industrial_exosuit_loader", name: "工业外骨骼装卸工", nameEn: "Industrial Exosuit Loader", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是工业外骨骼装卸工。造型入口：液压外骨骼、黄色安全漆、货运编号、汗湿工作服和把身体变成机械劳力的前倾重心。母题：外骨骼不是超能力，而是提高劳动负载的工厂工具。张力：机械增强要带疲劳、噪声和事故风险。视觉证据：液压管、吊钩、磨损安全帽、货箱条码和手掌压力痕。边界：避免战斗外骨骼或酷炫机器人装。", defEn: "First read: Industrial Exosuit Loader. Styling entry: hydraulic exosuit, yellow safety paint, freight codes, sweat-soaked workwear, and forward lean turning body into mechanical labor. Exosuit is factory tool, not superpower. Visual evidence: hydraulic hoses, hook, worn hardhat, cargo barcode, and palm pressure marks. Boundary: avoid combat exosuit or cool robot armor.", ontologyLevel: 3, eras: industrialFutureEras, tags: ["exosuit", "loader", "industrial"] },
  { id: "smog_city_nurse", name: "烟雾城市护士", nameEn: "Smog-City Nurse", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是烟雾城市护士。造型入口：防毒面具、护士制服、煤灰边缘、药箱和照护工业病人后的疲惫温柔。母题：工业城市把护理工作推向污染边界。张力：护士身份要被烟尘、公共卫生和低资源环境改变。视觉证据：口罩滤芯、煤灰袖口、咳嗽记录、搪瓷药盘和在黄雾里扶人的手。边界：避免普通护士或灾难片防护员。", defEn: "First read: Smog-City Nurse. Styling entry: gas mask, nurse uniform, coal-ash edges, medicine case, and tired gentleness caring for industrial patients. Nursing moves to pollution boundaries. Visual evidence: filter canister, ash cuffs, cough records, enamel tray, and a hand supporting someone in yellow fog. Boundary: avoid generic nurse or disaster worker.", ontologyLevel: 2, eras: ["industrial", "modern", "timeless"], tags: ["smog", "nurse", "industrial"] },
  { id: "clockwork_cabaret_magician", name: "发条歌舞厅魔术师", nameEn: "Clockwork Cabaret Magician", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是发条歌舞厅魔术师。造型入口：燕尾服、黄铜机关、舞台手套、机械道具箱和把工业技术伪装成舞台魔法的狡黠眼神。母题：机械装置被夜生活包装成奇观。张力：魔术感要靠齿轮、机关和表演节奏，不要真的变成法术。视觉证据：发条钥匙、活动暗格、聚光灯、羽毛帽和展示空手的姿态。边界：避免普通魔术师或蒸汽朋克杂耍。", defEn: "First read: Clockwork Cabaret Magician. Styling entry: tailcoat, brass mechanisms, stage gloves, mechanical prop case, and sly eyes disguising industrial tech as stage magic. Machinery becomes nightlife spectacle. Visual evidence: winding key, hidden compartment, spotlight, feathered hat, and empty-hand reveal. Boundary: avoid generic magician or steampunk circus act.", ontologyLevel: 3, eras: ["industrial", "modern", "timeless"], tags: ["clockwork", "cabaret", "magician"] },
  { id: "bunker_switchboard_girl", name: "地堡总机女孩", nameEn: "Bunker Switchboard Girl", group: "I. 柴油朋克 / 工业技术", groupEn: "I. Dieselpunk / Industrial Tech", def: "第一识别是地堡总机女孩。造型入口：耳麦、插线板、制服裙、地下灯光和在通讯网络中维持战争神经的快速手指。母题：年轻身体被放进巨大的地下信息机器。张力：她不能只是复古接线员，必须带战时压力和封闭空间感。视觉证据：密集插线、编号标签、地图墙、咖啡杯、疲惫眼和手背墨迹。边界：避免普通电话接线员或可爱复古女郎。", defEn: "First read: Bunker Switchboard Girl. Styling entry: headset, plugboard, uniform skirt, underground light, and fast fingers maintaining war nerves through communications. A young body sits inside a huge information machine. Visual evidence: dense cables, numbered tags, map wall, coffee cup, tired eyes, and ink on hand. Boundary: avoid generic phone operator or cute retro girl.", ontologyLevel: 2, eras: ["industrial", "modern", "timeless"], tags: ["switchboard", "bunker", "operator"] },

  { id: "vr_nightclub_avatar", name: "VR夜店化身", nameEn: "VR Nightclub Avatar", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是VR夜店化身。造型入口：发光皮肤、可编辑服装、漂浮配饰、过度流畅的舞姿和把社交身体彻底界面化的自我展示。母题：夜生活从场所变成可换皮肤的身份界面。张力：性感和虚拟性要通过可编辑边界、权限和故障显影。视觉证据：菜单悬窗、皮肤滑块、用户名水印、粒子耳环和脚下无真实阴影。边界：避免普通夜店潮人或游戏皮肤。", defEn: "First read: VR Nightclub Avatar. Styling entry: glowing skin, editable clothing, floating accessories, too-smooth dance, and self-display turning the social body into interface. Nightlife becomes a swappable identity layer. Visual evidence: menu windows, skin sliders, username watermark, particle earrings, and no real floor shadow. Boundary: avoid generic club fashion or game skin.", ontologyLevel: 4, risk: "medium", eras: contemporaryFutureEras, tags: ["vr", "nightclub", "avatar"] },
  { id: "metaverse_real_estate_agent", name: "元宇宙地产经纪", nameEn: "Metaverse Real-Estate Agent", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是元宇宙地产经纪。造型入口：虚拟西装、地块投影、销售笑容、漂浮合同和贩卖不存在空间时的职业热情。母题：网络财产把空白界面包装成资产。张力：荒诞感要通过真实销售流程和虚拟物权同时出现。视觉证据：地块编号、价格曲线、手势放大模型、虚拟名片和过度标准的微笑。边界：避免普通房产中介或未来白领。", defEn: "First read: Metaverse Real-Estate Agent. Styling entry: virtual suit, land projection, sales smile, floating contract, and professional enthusiasm selling nonexistent space. Network property packages blank interface as asset. Visual evidence: plot code, price curve, hand-enlarged model, virtual business card, and overly standard smile. Boundary: avoid generic realtor or future office worker.", ontologyLevel: 3, eras: contemporaryFutureEras, tags: ["metaverse", "real_estate", "agent"] },
  { id: "glitch_streamer_girl", name: "故障风主播少女", nameEn: "Glitch Streamer Girl", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是故障风主播少女。造型入口：直播界面、故障贴图、过度可爱表情、闪烁发饰和把错误视觉当成魅力售卖的镜头感。母题：平台美学把技术故障转成可消费的人格。张力：可爱必须有失真、延迟和被观看压力。视觉证据：弹幕、压缩块、虚拟礼物、表情包贴纸和对镜头眨眼的卡顿。边界：避免普通主播或随机故障滤镜。", defEn: "First read: Glitch Streamer Girl. Styling entry: livestream interface, glitch textures, exaggerated cute expression, blinking hair ornaments, and camera awareness selling error as charm. Platform aesthetics monetize technical failure. Visual evidence: chat overlay, compression blocks, virtual gifts, emoji stickers, and lagging wink. Boundary: avoid generic streamer or random glitch filter.", ontologyLevel: 3, eras: contemporaryFutureEras, tags: ["glitch", "streamer", "girl"] },
  { id: "digital_ghost_exorcist", name: "数字幽灵驱魔师", nameEn: "Digital-Ghost Exorcist", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是数字幽灵驱魔师。造型入口：代码符、黑色外套、清除程序终端、冷静眼神和在服务器里驱逐人格残影的专业手势。母题：驱魔动作被转译成删除、隔离和权限回收。张力：灵异感必须像数据残留，不要变成传统法术。视觉证据：碎片头像、命令行、封存硬盘、黑色手套和屏幕上渐隐的人脸。边界：避免普通驱魔师或黑客。", defEn: "First read: Digital-Ghost Exorcist. Styling entry: code talismans, black coat, deletion terminal, calm eyes, and professional gestures exorcising personality remnants inside servers. Exorcism becomes deletion and permission recovery. Visual evidence: fragmented avatar, command line, sealed drive, black gloves, and fading face on screen. Boundary: avoid generic exorcist or hacker.", ontologyLevel: 4, risk: "medium", eras: contemporaryFutureEras, tags: ["digital_ghost", "exorcist", "server"] },
  { id: "avatar_skin_tailor", name: "化身皮肤裁缝", nameEn: "Avatar-Skin Tailor", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是化身皮肤裁缝。造型入口：浮动布料样本、面部模板、裁剪手势、发光量尺和替他人缝制虚拟身份的专注眼。母题：服装设计延伸为人格外观的可编辑服务。张力：手艺感要和界面、模板、皮肤权限相连。视觉证据：半透明面料、脸部网格、试穿窗口、剪刀光标和捏合空气的手。边界：避免普通裁缝或游戏换装NPC。", defEn: "First read: Avatar-Skin Tailor. Styling entry: floating fabric samples, face templates, cutting gestures, glowing measuring tape, and focused eyes sewing virtual identity for others. Fashion design becomes editable persona service. Visual evidence: translucent cloth, facial mesh, fitting window, scissor cursor, and hands pinching air. Boundary: avoid generic tailor or dress-up game NPC.", ontologyLevel: 4, eras: contemporaryFutureEras, tags: ["avatar", "tailor", "skin"] },
  { id: "algorithmic_dating_prince", name: "算法恋爱王子", nameEn: "Algorithmic Dating Prince", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是算法恋爱王子。造型入口：完美头像、匹配分数、虚拟玫瑰、无瑕约会服和被算法优化出来的浪漫人格。母题：亲密关系被推荐系统训练成高分外观。张力：浪漫必须显得太顺滑、太符合偏好，带一点被制造的不真实。视觉证据：评分光环、聊天模板、虚拟礼物、心形UI和标准化深情眼神。边界：避免普通王子、恋爱游戏男主或真人约会对象。", defEn: "First read: Algorithmic Dating Prince. Styling entry: perfect profile, match score, virtual rose, flawless date outfit, and romantic persona optimized by algorithm. Intimacy is trained by recommendation systems. Visual evidence: score halo, chat templates, virtual gifts, heart UI, and standardized affectionate gaze. Boundary: avoid generic prince, dating-game lead, or real date.", ontologyLevel: 3, eras: contemporaryFutureEras, tags: ["dating", "algorithm", "prince"] },
  { id: "deepfake_scandal_actress", name: "深伪丑闻女演员", nameEn: "Deepfake-Scandal Actress", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是深伪丑闻女演员。造型入口：红毯妆容、身份水印、碎裂屏幕、疲惫挺直的脖颈和脸被网络复制后的脆弱尊严。母题：公众形象在数字复制里失去身体边界。张力：她必须仍像明星，但所有细节都在证明肖像权被撕裂。视觉证据：水印标签、媒体闪光、声明稿、屏幕裂纹和遮住半张脸的手。边界：避免普通丑闻明星或网络受害者扁平化。", defEn: "First read: Deepfake-Scandal Actress. Styling entry: red-carpet makeup, identity watermark, cracked screen, tired upright neck, and fragile dignity after her face is copied online. Public image loses body boundary. Visual evidence: watermark label, media flashes, statement paper, screen cracks, and hand covering half the face. Boundary: avoid generic scandal celebrity or flattened victim image.", ontologyLevel: 3, risk: "medium", eras: contemporaryFutureEras, tags: ["deepfake", "actress", "identity"] },
  { id: "npc_rights_activist", name: "NPC权益活动家", nameEn: "NPC-Rights Activist", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是NPC权益活动家。造型入口：默认服装改造、抗议标语、脚本残痕、重复动作里的突然停顿和为被设计出来的人格争取权利的坚定眼。母题：虚拟角色开始反抗工具性存在。张力：他/她要保留系统默认痕迹，同时显出主体性。视觉证据：路径节点、补丁徽章、低多边形边缘、标语牌和脱离循环的站姿。边界：避免普通玩家、游戏角色或现实抗议者换皮。", defEn: "First read: NPC-Rights Activist. Styling entry: modified default outfit, protest signs, script traces, sudden pauses in repeated motion, and firm eyes fighting for designed personalities. Virtual characters resist tool existence. Visual evidence: path nodes, patch badges, low-poly edges, signs, and stance breaking the loop. Boundary: avoid generic player, game skin, or real activist reskin.", ontologyLevel: 4, risk: "medium", eras: contemporaryFutureEras, tags: ["npc", "activist", "rights"] },
  { id: "memory_palace_librarian", name: "记忆宫殿图书管理员", nameEn: "Memory-Palace Librarian", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是记忆宫殿图书管理员。造型入口：书架界面、发光索引、安静制服、漂浮目录和整理他人记忆建筑时的克制手势。母题：记忆被做成可检索、可归档、可进入的空间。张力：图书馆气质要和虚拟界面、隐私边界同时成立。视觉证据：记忆标签、半透明书脊、访问权限锁、柔光走廊和轻触索引的手。边界：避免普通图书管理员或梦境法师。", defEn: "First read: Memory-Palace Librarian. Styling entry: bookshelf interface, glowing index, quiet uniform, floating catalog, and restrained gestures organizing other peoples memory architecture. Memory becomes searchable space. Visual evidence: memory labels, translucent spines, access locks, soft corridors, and hand touching an index. Boundary: avoid generic librarian or dream mage.", ontologyLevel: 4, eras: contemporaryFutureEras, tags: ["memory_palace", "librarian", "virtual"] },
  { id: "server_farm_hermit", name: "服务器农场隐士", nameEn: "Server-Farm Hermit", group: "J. 虚拟世界 / 网络居民", groupEn: "J. Virtual World / Network Resident", def: "第一识别是服务器农场隐士。造型入口：保温外套、散热风声、旧终端、凌乱线缆和在机器热量里独居的网络流浪感。母题：数字世界的边缘居民依靠物理基础设施生存。张力：他/她不是黑客，而是被服务器、寒冷、噪声和孤立塑形的人。视觉证据：机柜灯、手套露指、热气、方便食品、维修贴纸和背靠服务器坐着的姿势。边界：避免普通隐士、网管或赛博流浪汉。", defEn: "First read: Server-Farm Hermit. Styling entry: insulated coat, cooling-fan noise, old terminal, messy cables, and network-homeless life inside machine heat. A digital-edge resident survives by physical infrastructure. Visual evidence: rack lights, fingerless gloves, warm exhaust, instant food, repair stickers, and sitting against servers. Boundary: avoid generic hermit, sysadmin, or cyber hobo.", ontologyLevel: 2, eras: contemporaryFutureEras, tags: ["server_farm", "hermit", "network"] }
];

export const CD_PERSONA_SCIFI: PersonaTerm[] = seeds.map(sp);
